/* src/assets/js/01-core.js */
/* The only things the modules share. Everything else in each file stays
   private to it, so a module can be removed without breaking the others. */

window.Portfolio = {

  // One media query, read by anything that animates.
  reduceMotion: window.matchMedia('(prefers-reduced-motion: reduce)'),

  // Every setting from src/content/aquarium.yaml, written into the page by
  // the build. Also reachable as Aquarium.config, which is the name to use
  // when trying values in the console.
  aquarium: (() => {
    const el = document.getElementById('aquarium-config');
    try {
      return el ? JSON.parse(el.textContent) : {};
    } catch (err) {
      console.error('aquarium.yaml did not survive the build as valid JSON:', err);
      return {};
    }
  })(),

  // The sound module fills these in once the audio graph exists. Until then
  // calling one does nothing, so nothing else has to check.
  sound: { tap() {}, crack() {}, shatter() {}, splash() {}, bubble() {} }

};


/* The aquarium's own front door: the settings, the state everything reads,
   and the two things worth doing by hand.

       Aquarium.config.fish.dash_distance = 120
       Aquarium.break_()     skip the tapping
       Aquarium.reset()      put him back in a whole bowl
*/
window.Aquarium = (() => {
  'use strict';

  const config = Portfolio.aquarium;

  /* Settings are read through here rather than straight off the object, so a
     value deleted from the YAML falls back to something sensible instead of
     stopping the page, and an edit in the console is picked up on the next
     frame. */
  function get(path, fallback) {
    let node = config;
    for (const key of path.split('.')) {
      if (node == null || typeof node !== 'object') return fallback;
      node = node[key];
    }
    if (node === undefined || node === null) return fallback;
    return node;
  }

  /* A [low, high] pair in the YAML means "somewhere in here". A single number
     means exactly that. Either is accepted wherever a range is read. */
  function range(path, lo, hi) {
    const v = get(path, null);
    if (Array.isArray(v) && v.length >= 2) return [Number(v[0]), Number(v[1])];
    if (typeof v === 'number') return [v, v];
    return [lo, hi];
  }

  const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
  const lerp  = (a, b, t) => a + (b - a) * t;
  const rand  = (a, b) => a + Math.random() * (b - a);
  const pick  = ([a, b]) => rand(a, b);

  function rgb(hex) {
    const h = String(hex || '').replace('#', '');
    const n = h.length === 3
      ? h.split('').map(c => c + c).join('')
      : h.padEnd(6, '0').slice(0, 6);
    const v = parseInt(n, 16);
    return { r: (v >> 16) & 255, g: (v >> 8) & 255, b: v & 255 };
  }

  function mix(a, b, t) {
    const x = typeof a === 'string' ? rgb(a) : a;
    const y = typeof b === 'string' ? rgb(b) : b;
    return {
      r: Math.round(lerp(x.r, y.r, t)),
      g: Math.round(lerp(x.g, y.g, t)),
      b: Math.round(lerp(x.b, y.b, t))
    };
  }

  const css  = (c, alpha) => alpha === undefined
    ? `rgb(${c.r}, ${c.g}, ${c.b})`
    : `rgba(${c.r}, ${c.g}, ${c.b}, ${alpha})`;

  /* Everything the modules need to know about each other. One object rather
     than events: there are four of them, they all run inside one frame, and
     this stays readable. */
  const state = {
    broken: false,       // has the glass gone
    taps: 0,             // how many times it has been hit
    breakTime: 0,        // when it went, in scene seconds
    bowl: null,          // where the glass is on screen, in CSS pixels
    surfaceY: 0,         // the waterline, in screen pixels (may be negative)
    surfacePageY: 0,     // the same line, in page pixels — it never moves
    pour: 0,             // how far the water has come up, 0 to 1
    lastClick: null,     // where the page was last clicked, for the dash
    depth: 0,            // 0 at the surface, 1 as deep as the page goes
    pointer: { x: 0, y: 0, moved: 0, inside: false }
  };

  /* One multiplier for anything that moves on its own. Visitors who have
     asked their system for less movement get the `motion` block's share of it;
     everyone else gets all of it. What they do themselves — clicking, and the
     fish coming over — is never slowed down. */
  function motion() {
    if (get('motion.respect_reduced_motion', true) === false) return 1;
    return Portfolio.reduceMotion.matches
      ? clamp(Number(get('motion.reduced_scale', 0.3)), 0, 1)
      : 1;
  }

  return { config, get, range, state, motion, clamp, lerp, rand, pick, rgb, mix, css };
})();

/* src/assets/js/02-nav.js */
/* The year in the footer, and the sticky nav bar. */

(() => {
  'use strict';

  const yearEl = document.getElementById('year');
  if (yearEl) yearEl.textContent = String(new Date().getFullYear());

  // The sticky nav stays out of the way until the title has scrolled past.
  // While the page is locked it is hidden by the stylesheet, so there is
  // nothing extra to do here.
  const topbar = document.getElementById('topbar');
  const titleBand = document.querySelector('.band--title');
  if (topbar && titleBand) {
    if (window.IntersectionObserver) {
      new IntersectionObserver(([entry]) => {
        topbar.classList.toggle('is-visible', !entry.isIntersecting);
      }, { threshold: 0 }).observe(titleBand);
    } else {
      const onScroll = () => topbar.classList.toggle(
        'is-visible', window.scrollY > titleBand.offsetHeight);
      window.addEventListener('scroll', onScroll, { passive: true });
      onScroll();
    }
  }

})();

/* src/assets/js/03-media.js */
/* Project previews: empty-state fallback, and play on hover. */

(() => {
  'use strict';

  /* A row's video is optional. Until a clip is dropped into media/, the panel
     falls back to an empty water panel instead of a broken video box.        */

  /* A studio logo is optional too. Until media/<logo>.png exists, the corner
     falls back to the studio's name. */
  document.querySelectorAll('.media-studio-logo').forEach(img => {
    const bare = () => {
      const corner = img.closest('.media-studio');
      if (corner) corner.classList.remove('has-logo');
      img.remove();
    };
    img.addEventListener('error', bare);
    // the file may already have failed before this script ran
    if (img.complete && !img.naturalWidth) bare();
  });

  /* A reference's icon is fetched from its site. Offline, or when there is
     none, the bubble shows the site's first letter instead. */
  document.querySelectorAll('.ref-icon img').forEach(img => {
    const bare = () => {
      img.parentElement.classList.add('is-bare');
      img.remove();
    };
    img.addEventListener('error', bare);
    if (img.complete && !img.naturalWidth) bare();
  });

  /* A panel with more than one picture (a hero panel, or any media named as
     a folder) fades from each to the next. Each panel keeps its own clock
     and holds every picture for a fresh random time (`hero.hold` in
     aquarium.yaml), so they never change together. The hero panels stop
     once the glass is broken: they are gone by then. */
  const { get, range, pick } = Aquarium;
  document.querySelectorAll('.slides').forEach(set => {
    const photos = [...set.querySelectorAll('.slide')];
    set.style.setProperty('--slide-fade', Math.max(0, Number(get('hero.fade', 2))) + 's');
    if (photos.length < 2 || Portfolio.reduceMotion.matches) return;
    const hero = !!set.closest('.showcase');
    let on = 0;
    const next = () => {
      if (hero && document.body.classList.contains('is-breaking')) return;
      if (!document.hidden) {
        photos[on].classList.remove('is-on');
        on = (on + 1) % photos.length;
        photos[on].classList.add('is-on');
      }
      setTimeout(next, pick(range('hero.hold', 7, 9)) * 1000);
    };
    setTimeout(next, pick(range('hero.hold', 7, 9)) * 1000);
  });

  document.querySelectorAll('.media').forEach(fig => {
    if (fig.querySelector('.slides')) return;      // pictures, nothing to play
    // its own clip, not the cover waiting over a split thumbnail
    const video = fig.querySelector('video:not(.media-cover video)');
    if (!video) { fig.classList.add('is-empty'); return; }

    const markEmpty = () => fig.classList.add('is-empty');
    const poster = video.getAttribute('poster');

    // Either file alone is enough: a panel with a .jpg and no .mp4 keeps
    // showing the picture, it just has nothing to play on hover; one with
    // an .mp4 and no picture shows the clip's first frame (no poster).
    if (!video.querySelector('source')) video.dataset.noClip = '';
    let still = false;
    if (poster) {
      const probe = new Image();
      probe.onload = () => { still = true; };
      probe.onerror = markEmpty;
      probe.src = poster;
    }
    video.addEventListener('error', () => {
      video.dataset.noClip = '';
      if (!still) markEmpty();
    }, true);

    if (Portfolio.reduceMotion.matches) {
      video.setAttribute('controls', '');
      return;
    }

    const play = () => {
      if (fig.classList.contains('is-empty') || 'noClip' in video.dataset) return;
      const p = video.play();
      if (p && p.catch) p.catch(() => {});
    };
    const stop = () => { video.pause(); };

    // On a detail page the clips play on their own while they're on screen;
    // in the gallery they wait for the row to be hovered.
    if (fig.closest('.detail-layer') && window.IntersectionObserver) {
      new IntersectionObserver(([entry]) => {
        if (entry.isIntersecting) play(); else stop();
      }, { threshold: 0.25 }).observe(fig);
      return;
    }

    const row = fig.closest('.entry, .showcase-item') || fig;
    row.addEventListener('pointerenter', play);
    row.addEventListener('pointerleave', stop);
    row.addEventListener('focusin', play);
    row.addEventListener('focusout', stop);
  });

  /* A professional project's row shows its cover in the thumbnail's place
     while it is hovered: the clip, playing, or else the picture. It is only
     fetched on the first hover, and only faded up once it is actually
     playing (or loaded), so a slow connection keeps the thumbnail rather
     than showing a blank. Leaving the row fades it back out and pauses it;
     the next hover carries on from there. Not for reduced motion. */
  document.querySelectorAll('.media-cover').forEach(layer => {
    const el = layer.querySelector('video, img');
    if (!el || Portfolio.reduceMotion.matches) return;
    const row = layer.closest('.entry') || layer.parentElement;
    const fig = layer.parentElement;
    const isVideo = el.tagName === 'VIDEO';
    let hovered = false;

    // the studio's logo is kept over the cover (07-work.css, .is-covered)
    const show = () => {
      if (!hovered) return;
      layer.classList.add('is-showing');
      fig.classList.add('is-covered');
    };
    el.addEventListener(isVideo ? 'playing' : 'load', show);

    const enter = () => {
      hovered = true;
      if (!el.getAttribute('src')) el.src = el.dataset.src;
      if (isVideo) {
        const p = el.play();
        if (p && p.catch) p.catch(() => {});
        if (!el.paused && el.readyState >= 3) show();
      } else if (el.complete && el.naturalWidth) {
        show();
      }
    };
    const leave = () => {
      hovered = false;
      layer.classList.remove('is-showing');
      fig.classList.remove('is-covered');
      if (isVideo) el.pause();
    };

    row.addEventListener('pointerenter', enter);
    row.addEventListener('pointerleave', leave);
    row.addEventListener('focusin', enter);
    row.addEventListener('focusout', leave);
  });

})();

/* src/assets/js/04-detail.js */
/* Detail pages: open, close, focus, and the URL for each one. */

(() => {
  'use strict';

  const main       = document.getElementById('main');
  const layer      = document.getElementById('detail-layer');
  const scroller   = document.getElementById('detail-scroll');
  const closeBtn   = document.getElementById('detail-close');
  const details    = Array.from(document.querySelectorAll('.detail'));
  const byProject  = new Map(details.map(d => [d.dataset.project, d]));
  let   lastOpener = null;

  function openDetail(id) {
    const panel = byProject.get(id);
    if (!panel) return false;

    details.forEach(d => { d.hidden = (d !== panel); });
    // the page takes the colour of the shelf the project sits on
    layer.classList.toggle('is-hobby', panel.classList.contains('detail--hobby'));
    layer.hidden = false;
    document.body.classList.add('detail-open');
    main.inert = true;
    main.setAttribute('aria-hidden', 'true');
    if (scroller) scroller.scrollTop = 0;

    const title = panel.querySelector('.detail-title');
    if (title) title.focus({ preventScroll: true });
    return true;
  }

  function closeDetail() {
    if (layer.hidden) return;
    layer.hidden = true;
    details.forEach(d => { d.hidden = true; });
    document.body.classList.remove('detail-open');
    main.inert = false;
    main.removeAttribute('aria-hidden');

    if (lastOpener) {
      lastOpener.focus({ preventScroll: true });
      lastOpener = null;
    }
  }

  function idFromHash() {
    return location.hash ? location.hash.slice(1) : '';
  }

  function syncToHistory() {
    const id = (history.state && history.state.detail) || idFromHash();
    if (byProject.has(id)) openDetail(id);
    else closeDetail();
  }

  document.querySelectorAll('.entry-link').forEach(link => {
    link.addEventListener('click', event => {
      const id = link.dataset.project;
      if (!byProject.has(id) || event.metaKey || event.ctrlKey || event.shiftKey) return;
      event.preventDefault();
      lastOpener = link;
      history.pushState({ detail: id }, '', '#' + id);
      openDetail(id);
    });
  });

  if (closeBtn) closeBtn.addEventListener('click', () => history.back());

  window.addEventListener('popstate', syncToHistory);

  document.addEventListener('keydown', event => {
    if (event.key === 'Escape' && !layer.hidden) history.back();
  });

  // Deep link: someone opened the page on #infernal-dante. The glass is
  // already broken in that case — they asked for a project, not a puzzle.
  if (byProject.has(idFromHash())) {
    Aquarium.state.deepLinked = true;
    openDetail(idFromHash());
  }

})();

/* src/assets/js/05-sound.js */
/* Glass, and water. All synthesised — there is no audio file to ship.

   A tap is a filtered noise transient, two ringing partials and the low thud
   of the panel flexing. A crack is the same with the ring bent downwards. The
   shatter is a handful of those at once, falling.

   The splash is the one that has to be built rather than filtered: noise
   alone only ever sounds like a hiss. What makes water sound like water is
   the bubbles — a pocket of trapped air rings at a pitch set by its size, and
   shrinks as it rises, so the note slides upwards as it fades. One big one
   for the cavity he leaves behind him and a scatter of small ones after it,
   under a short bright hit and a thin wash of falling droplets.

   Levels come from the `sound` block in src/content/aquarium.yaml. */

(() => {
  'use strict';

  const cfg = (path, fallback) => Aquarium.get('sound.' + path, fallback);

  const sound = (() => {
    let ctx = null;
    let master = null;
    let enabled = cfg('enabled', true) !== false;

    function ready() {
      if (!enabled) return false;
      if (!ctx) {
        const AC = window.AudioContext || window.webkitAudioContext;
        if (!AC) return false;
        ctx = new AC();
        master = ctx.createGain();
        const soften = ctx.createBiquadFilter();
        soften.type = 'lowpass';
        soften.frequency.value = 9000;
        master.connect(soften).connect(ctx.destination);
      }
      master.gain.value = Number(cfg('volume', 0.5)) || 0;
      if (ctx.state === 'suspended') ctx.resume();
      return true;
    }

    /* A burst of noise, shaped by an envelope and a filter. */
    function noise(t, { dur, type, freq, q, gain, decay }) {
      const buf = ctx.createBuffer(1, Math.ceil(ctx.sampleRate * dur), ctx.sampleRate);
      const data = buf.getChannelData(0);
      for (let i = 0; i < data.length; i++) {
        data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / data.length, decay);
      }
      const src = ctx.createBufferSource();
      src.buffer = buf;
      const filter = ctx.createBiquadFilter();
      filter.type = type;
      filter.frequency.value = freq;
      filter.Q.value = q;
      const g = ctx.createGain();
      g.gain.value = gain;
      src.connect(filter).connect(g).connect(master);
      src.start(t);
      return filter;
    }

    /* One ringing partial of the glass. */
    function ring(t, freq, amp, decay, bend) {
      const osc = ctx.createOscillator();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, t);
      if (bend) osc.frequency.exponentialRampToValueAtTime(freq * bend, t + decay);
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.0001, t);
      g.gain.linearRampToValueAtTime(amp, t + 0.004);
      g.gain.exponentialRampToValueAtTime(0.0001, t + decay);
      osc.connect(g).connect(master);
      osc.start(t);
      osc.stop(t + decay + 0.03);
    }

    function tap(strength = 1) {
      if (!ready()) return;
      const s = strength * Number(cfg('tap', 1));
      const t = ctx.currentTime;

      noise(t, { dur: 0.09, type: 'bandpass', freq: 3100 + Math.random() * 900,
                 q: 1.1, gain: 0.3 * s, decay: 6 });

      [{ f: 1840, a: 0.16, d: 0.17 },
       { f: 3160, a: 0.11, d: 0.12 },
       { f: 5380, a: 0.04, d: 0.07 }].forEach(p => {
        ring(t, p.f * (0.97 + Math.random() * 0.06), p.a * s, p.d);
      });

      const low = ctx.createOscillator();
      low.type = 'sine';
      low.frequency.setValueAtTime(185, t);
      low.frequency.exponentialRampToValueAtTime(88, t + 0.08);
      const lg = ctx.createGain();
      lg.gain.setValueAtTime(0.2 * s, t);
      lg.gain.exponentialRampToValueAtTime(0.0001, t + 0.1);
      low.connect(lg).connect(master);
      low.start(t);
      low.stop(t + 0.13);
    }

    /* A tap that doesn't quite hold: the ring slides down instead of staying
       put, which is what a crack sounds like. */
    function crack(strength = 1) {
      if (!ready()) return;
      const s = strength * Number(cfg('crack', 1));
      const t = ctx.currentTime;

      tap(strength * 0.8);
      noise(t + 0.01, { dur: 0.16, type: 'highpass', freq: 2400,
                        q: 0.6, gain: 0.26 * s, decay: 3 });
      ring(t + 0.012, 2400, 0.1 * s, 0.26, 0.55);
      ring(t + 0.02, 1260, 0.08 * s, 0.3, 0.6);
    }

    /* The break: the panel letting go, then the pieces landing. */
    function shatter(strength = 1) {
      if (!ready()) return;
      const s = strength * Number(cfg('shatter', 1));
      const t = ctx.currentTime;

      noise(t, { dur: 0.5, type: 'highpass', freq: 1800, q: 0.4,
                 gain: 0.32 * s, decay: 2.2 });

      for (let i = 0; i < 9; i++) {
        const at = t + 0.02 + Math.random() * 0.42;
        ring(at, 2200 + Math.random() * 4200, (0.05 + Math.random() * 0.06) * s,
             0.08 + Math.random() * 0.18, 0.8);
      }

      const low = ctx.createOscillator();
      low.type = 'triangle';
      low.frequency.setValueAtTime(140, t);
      low.frequency.exponentialRampToValueAtTime(52, t + 0.3);
      const lg = ctx.createGain();
      lg.gain.setValueAtTime(0.26 * s, t);
      lg.gain.exponentialRampToValueAtTime(0.0001, t + 0.34);
      low.connect(lg).connect(master);
      low.start(t);
      low.stop(t + 0.36);
    }

    /* A bubble in water, which is the whole trick to making this sound wet.

       A pocket of air trapped under the surface rings at a pitch set by how
       big it is, and it shrinks as it rises and loses air — so the note slides
       *up* as it dies away, quickly. That rising blip is what the ear hears as
       water; noise on its own is only ever a hiss. Small bubbles are high and
       short, the big one left by something heavy going in is low and longer. */
    function bubble_(t, freq, rise, amp, dur) {
      const osc = ctx.createOscillator();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, t);
      osc.frequency.exponentialRampToValueAtTime(freq * rise, t + dur);
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.0001, t);
      g.gain.linearRampToValueAtTime(amp, t + 0.005);
      g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      osc.connect(g).connect(master);
      osc.start(t);
      osc.stop(t + dur + 0.03);
    }

    /* Water taking him. Four things happening at once, in the order water
       does them:

         the hit     a short burst of noise, bright at the front and closing
                     down fast — the surface being broken
         the cavity  the big bubble he leaves behind him, low and rising
         the fizz    a scatter of smaller bubbles over the next third of a
                     second, each one higher and shorter than the last
         the wash    the droplets coming back down, a thin hiss under it all

       Nothing here is a recording: it is four oscillators and two bursts of
       noise. `strength` is how hard he went in — it moves the pitch of the
       cavity, how many bubbles there are and how long the wash runs, rather
       than simply turning the whole thing up. */
    function splash(strength = 1) {
      if (!ready()) return;
      const s = Math.min(strength, 1.6) * Number(cfg('splash', 0.9));
      const big = Math.min(Math.max(strength, 0.2), 1.6);   // how heavy it was
      const t = ctx.currentTime;
      const r = (a, b) => a + Math.random() * (b - a);

      // 1. the surface breaking: bright, and shutting down within a tenth
      const hit = noise(t, { dur: 0.4, type: 'bandpass', freq: 1800,
                             q: 0.55, gain: 0.34 * s, decay: 4.5 });
      hit.frequency.setValueAtTime(2200 + r(-300, 400), t);
      hit.frequency.exponentialRampToValueAtTime(420, t + 0.13);
      hit.frequency.exponentialRampToValueAtTime(190, t + 0.38);

      // 2. the cavity behind him — the "bloop". Lower the harder he hit.
      bubble_(t + 0.012, (300 - big * 110) * r(0.92, 1.08), r(1.8, 2.4),
              0.17 * s, 0.1 + big * 0.055);

      // 3. the fizz: a handful of smaller ones, thinning out
      const n = Math.round(4 + big * 7);
      for (let i = 0; i < n; i++) {
        const when = t + 0.03 + Math.pow(Math.random(), 1.5) * (0.16 + big * 0.22);
        bubble_(when, r(420, 1250), r(1.5, 2.3),
                r(0.012, 0.05) * s, r(0.035, 0.085));
      }

      // 4. the wash of droplets falling back in
      const wash = noise(t + 0.05, { dur: 0.5 + big * 0.5, type: 'highpass',
                                     freq: 1500, q: 0.5,
                                     gain: 0.085 * s * big, decay: 1.5 });
      wash.frequency.setValueAtTime(900, t + 0.05);
      wash.frequency.linearRampToValueAtTime(2600, t + 0.5 + big * 0.4);

      // and a little weight under the whole thing, for a heavy landing
      if (big > 0.6) {
        const low = ctx.createOscillator();
        low.type = 'sine';
        low.frequency.setValueAtTime(130, t);
        low.frequency.exponentialRampToValueAtTime(58, t + 0.18);
        const lg = ctx.createGain();
        lg.gain.setValueAtTime(0.1 * s * big, t);
        lg.gain.exponentialRampToValueAtTime(0.0001, t + 0.22);
        low.connect(lg).connect(master);
        low.start(t);
        low.stop(t + 0.26);
      }
    }

    /* One bubble leaving his mouth: a short upward blip. */
    function bubble(strength = 1) {
      if (!ready()) return;
      const t = ctx.currentTime;
      const osc = ctx.createOscillator();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(420 + Math.random() * 280, t);
      osc.frequency.exponentialRampToValueAtTime(1400 + Math.random() * 600, t + 0.07);
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.0001, t);
      g.gain.linearRampToValueAtTime(0.05 * strength, t + 0.008);
      g.gain.exponentialRampToValueAtTime(0.0001, t + 0.09);
      osc.connect(g).connect(master);
      osc.start(t);
      osc.stop(t + 0.11);
    }

    return {
      tap, crack, shatter, splash, bubble,
      get enabled() { return enabled; },
      set enabled(v) { enabled = v; if (!v && ctx) ctx.suspend(); }
    };
  })();

  // A viewer's own choice is remembered, and wins over `sound.enabled`.
  const soundKey = 'portfolio.sound';
  try {
    const saved = localStorage.getItem(soundKey);
    if (saved !== null) sound.enabled = saved === 'on';
  } catch (err) { /* no storage: the setting stands */ }

  const btn = document.getElementById('sound-toggle');
  if (btn) {
    const paint = () => {
      // the icon follows aria-pressed (see 06-title.css)
      btn.setAttribute('aria-pressed', String(sound.enabled));
      btn.title = sound.enabled ? 'Sound on' : 'Sound off';
    };
    paint();
    btn.addEventListener('click', () => {
      sound.enabled = !sound.enabled;
      paint();
      try { localStorage.setItem(soundKey, sound.enabled ? 'on' : 'off'); } catch (err) { /* fine */ }
      if (sound.enabled) sound.tap(0.8);
    });
  }

  // Hand the whole kit to anything else that wants it (the bowl and the fish).
  Portfolio.sound = sound;

})();

/* src/assets/js/06-depth.js */
/* Depth. How far down the page you are is how deep the water is, and the
   light goes with it: bright teal at the surface, nearly black at the bottom.

   This module owns the two questions everything else asks —

       Aquarium.depthAt(screenY)   how deep is this point, 0 to 1
       Aquarium.colorAt(depth)     what colour is the water there

   — and keeps `--depth` on the page in step, so the stylesheet can darken the
   panels along with it. The numbers are the `depth` block of aquarium.yaml. */

(() => {
  'use strict';

  const { clamp, mix, get } = Aquarium;
  const state = Aquarium.state;

  // The page's own height, measured rarely rather than every frame.
  let pageHeight = 0;
  function measure() {
    const doc = document.documentElement;
    pageHeight = Math.max(doc.scrollHeight, doc.offsetHeight, window.innerHeight);
  }
  measure();

  /* Where, on the page, the water is as dark as it is going to get. */
  function floorY() {
    const full = clamp(Number(get('depth.full_at', 0.85)) || 0.85, 0.1, 1);
    return Math.max(window.innerHeight * 0.6, pageHeight * full);
  }

  Aquarium.depthAt = function (screenY) {
    const surface = state.surfacePageY;
    const pageY = window.scrollY + screenY;
    const span = Math.max(1, floorY() - surface);
    const d = clamp((pageY - surface) / span, 0, 1);
    const curve = Number(get('depth.curve', 1.15)) || 1;
    return Math.pow(d, curve);
  };

  /* Three stops: the surface, halfway, and the bottom. */
  Aquarium.colorAt = function (d) {
    const shallow = get('depth.shallow_color', '#0d7fa4');
    const middle  = get('depth.mid_color', '#06495f');
    const deep    = get('depth.deep_color', '#02191f');
    return d < 0.5
      ? mix(shallow, middle, d * 2)
      : mix(middle, deep, (d - 0.5) * 2);
  };

  /* The one number the stylesheet needs. Written only when it has actually
     moved — a style write on every frame of a scroll is a repaint on every
     frame of a scroll. */
  let written = -1;
  function paint() {
    const d = Aquarium.depthAt(window.innerHeight * 0.5);
    state.depth = d;
    const shown = Math.round(d * 100) / 100;
    if (shown !== written) {
      written = shown;
      document.documentElement.style.setProperty('--depth', String(shown));
    }
  }

  window.addEventListener('scroll', paint, { passive: true });
  window.addEventListener('resize', () => { measure(); paint(); });

  // The page gets taller the moment the sections are revealed, so take the
  // measurement again whenever something changes size.
  if (window.ResizeObserver) {
    const ro = new ResizeObserver(() => { measure(); paint(); });
    ro.observe(document.body);
  }

  Aquarium.remeasure = () => { measure(); paint(); };
  paint();

})();

/* src/assets/js/07-water.js */
/* The water, and the loop everything else draws inside.

   One canvas, fixed to the viewport, is the whole scene: the water, the inside
   of the bowl, the shoal, the fish, the glass. They are kept apart as layers
   with an order, so each module can add its own and not care about the others:

       Aquarium.scene.add(50, (ctx, env) => { ... });

   Low numbers are far away. 10 is the water, 20 the inside of the bowl, 30 the
   shoal, 50 the fish, 75 the glass over the top of him, 90 the surface itself.

   The canvas is fixed, so the water does not scroll with the page: scrolling
   takes you down through it instead, which is the whole idea. The waterline is
   remembered as a point on the page, and where that lands on the screen is
   what the first layer draws from. */

(() => {
  'use strict';

  const { get, clamp, lerp, rand, mix, motion, colorAt, depthAt, css } = Aquarium;
  const state = Aquarium.state;

  const host = document.getElementById('aquarium');
  const canvas = document.getElementById('aquarium-canvas');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');

  // ------------------------------------------------------------- canvas --

  const view = { w: 0, h: 0, dpr: 1 };

  function resize() {
    view.dpr = Math.min(window.devicePixelRatio || 1, 2);
    view.w = window.innerWidth;
    view.h = window.innerHeight;
    canvas.width = Math.round(view.w * view.dpr);
    canvas.height = Math.round(view.h * view.dpr);
    ctx.setTransform(view.dpr, 0, 0, view.dpr, 0, 0);
    scatter();
  }

  // -------------------------------------------------------------- layers --

  const layers = [];
  const scene = {
    view,
    add(order, draw) {
      layers.push({ order, draw });
      layers.sort((a, b) => a.order - b.order);
    },
    ripple(x, y, strength = 1) {
      ripples.push({ x, y, born: clock, strength, seed: rand(0, Math.PI * 2) });
      if (ripples.length > 24) ripples.shift();
    },

    /* Something went through the line. Two things come of it: a wave that
       travels out along the surface in both directions, and a crown of
       droplets thrown up off the point it went through.

       `strength` is roughly how hard — 1 is the fish landing, 2 is the fish
       landing from a height. `dir` is +1 going down into the water, -1 coming
       up out of it, which only changes how the droplets are thrown. */
    splash(x, strength = 1, dir = 1) {
      const s = clamp(strength, 0.1, 2.5);
      splashes.push({ x, born: clock, strength: s, seed: rand(0, Math.PI * 2) });
      if (splashes.length > 8) splashes.shift();

      const n = Math.round(Number(get('water.splash_drops', 16)) * s);
      const up = Number(get('water.splash_throw', 420));
      for (let i = 0; i < n; i++) {
        // across the crown, and hardest up the middle of it
        const across = rand(-1, 1);
        drops.push({
          x: x + across * 30 * s,
          y: state.surfaceY + rand(-4, 6),
          vx: across * rand(50, 240) * s,
          vy: -up * s * rand(0.35, 1) * (1 - Math.abs(across) * 0.45)
              * (dir < 0 ? 1.15 : 1),
          r: rand(1.1, 3.4) * (0.8 + s * 0.3),
          born: clock,
          life: rand(0.45, 1.15) * (0.7 + s * 0.3)
        });
      }
      if (drops.length > 260) drops.splice(0, drops.length - 260);
    }
  };
  Aquarium.scene = scene;

  // ------------------------------------------------------- the waterline --

  /* The waterline. Once he has finished turning over at the top of his leap,
     it comes up from below the screen and climbs, without stopping, to
     `surface_end` — he lands in it somewhere on the way up. It is kept in page coordinates, which do not
     change when the page scrolls: scrolling takes you down past it, it does
     not follow you. */
  function restingSurface() {
    const start = Number(get('water.surface_start', 0.5));
    return window.scrollY + view.h * start;
  }

  let resting = 0;
  let rise = null;
  let risen = false;       // it has finished climbing and stays where it is

  function remeasureSurface() {
    if (!state.broken && !rise) resting = restingSurface();
  }

  /* Called once, when he starts to fall. A second call is ignored, so the
     climb is never restarted halfway up.

     Where it comes to rest is the top of the pond (#waterline), the band
     under the opening screen. The page goes down with it while it climbs, so
     that on screen it does what it always did — comes up from below and
     stops `surface_end` from the top — and by the time it stops the pond is
     in view and he has fallen past the quote. Without a #waterline it simply
     stops `surface_end` from the top of the screen, and the page stays put. */
  Aquarium.raiseSurface = () => {
    if (rise || risen) return;
    const end = Number(get('water.surface_end', 0.17));
    const scrollFrom = window.scrollY;
    const mark = document.getElementById('waterline');
    const to = mark
      ? mark.getBoundingClientRect().top + scrollFrom
      : scrollFrom + view.h * end;
    rise = {
      from: scrollFrom + view.h + 40,
      to,
      at: clock,
      time: Math.max(0.2, Number(get('water.rise_time', 3.4))),
      scrollFrom,
      scrollTo: mark ? Math.max(0, to - view.h * end) : scrollFrom
    };
    resting = rise.from;
    // the page is being moved for him, so he isn't to be carried with it
    state.autoScroll = rise.scrollTo !== scrollFrom;
    // After a hero click the page doesn't stop where the water does: the
    // bowl module takes the scroll from here and carries it on down to the
    // group, and the water only climbs.
    if (state.heading && Aquarium.leadRise && Aquarium.leadRise({ ...rise })) rise.led = true;
  };

  Aquarium.dropSurface = () => {
    rise = null; risen = false; state.autoScroll = false; remeasureSurface();
  };

  /* The page above the line has been cut away by `by` pixels: the line is
     that much nearer the top of the page now, though not on the screen.
     If it is still climbing (the dive given up partway, by a scroll), the
     climb moves with it. */
  Aquarium.shiftSurface = by => {
    resting -= by;
    if (rise) { rise.from -= by; rise.to -= by; rise.scrollFrom -= by; rise.scrollTo -= by; }
  };

  /* Whether the line is still on its way up. He dives until it isn't. */
  Aquarium.surfaceRising = () => !!rise;

  /* And how long it has left to go, in seconds; 0 once it is up. */
  Aquarium.surfaceLeft = () => rise ? Math.max(0, rise.at + rise.time - clock) : 0;

  /* One steady climb, slowing down only over the last `rise_ease` of it, so
     it never looks as if it has stopped partway. Starts at 0, ends at 1. */
  function steady(p) {
    const k = clamp(Number(get('water.rise_ease', 0.15)), 0.01, 1);
    const v = 1 / (1 - k / 2);
    if (p < 1 - k) return p * v;
    const q = p - (1 - k);
    return ((1 - k) + q - (q * q) / (2 * k)) * v;
  }

  function climb() {
    if (!rise) return;
    const p = clamp((clock - rise.at) / rise.time, 0, 1);
    resting = lerp(rise.from, rise.to, steady(p));
    // 'instant', or the stylesheet's smooth scrolling would chase every frame
    if (state.autoScroll && !rise.led) {
      window.scrollTo({ top: lerp(rise.scrollFrom, rise.scrollTo, steady(p)), behavior: 'instant' });
    }
    if (p >= 1) {
      if (!rise.led) state.autoScroll = false;
      rise = null;
      risen = true;
      if (Aquarium.onSettled) Aquarium.onSettled();
    }
  }

  // ------------------------------------------------------------- drifting --

  let motes = [];
  let ripples = [];
  const splashes = [];     // waves running out along the line
  const drops = [];        // and what was thrown up off it

  function scatter() {
    const count = Math.round(Number(get('water.motes', 90)));
    motes = [];
    for (let i = 0; i < count; i++) {
      motes.push({
        x: rand(0, view.w),
        y: rand(0, view.h),
        r: rand(0.6, 2.2),
        drift: rand(-6, 6),
        rise: rand(4, 16),
        phase: rand(0, Math.PI * 2)
      });
    }
  }

  // --------------------------------------------------------------- water --

  /* The air starts out the colour of the water, so the bowl sits in one
     unbroken tank. When the glass goes it clears to `sky_color`, on the same
     curve as his leap, and is fully clear just as he reaches the top of it. */
  function skyColor(t) {
    const water = get('depth.shallow_color', '#06455a');
    const air = get('depth.sky_color', '#0d7fa4');
    if (!state.broken) return mix(water, air, 0);
    const rise = Math.max(0.2, Number(get('fish.leap_rise', 1)));
    const up = clamp((t - state.breakTime) / rise, 0, 1);
    return mix(water, air, 1 - (1 - up) * (1 - up));
  }

  function drawWater(ctx, env) {
    const { t, w, h } = env;
    const surf = state.surfaceY;
    const sky = css(skyColor(t));

    // Above the line is air, and before the break it is all there is.
    if (surf > 0) {
      ctx.fillStyle = sky;
      ctx.fillRect(0, 0, w, Math.min(h, surf + 1));
      // the light falls off a little towards the top of the screen
      const fade = ctx.createLinearGradient(0, 0, 0, Math.min(h, surf));
      fade.addColorStop(0, 'rgba(0, 0, 0, .16)');
      fade.addColorStop(1, 'rgba(0, 0, 0, 0)');
      ctx.fillStyle = fade;
      ctx.fillRect(0, 0, w, Math.max(0, Math.min(h, surf)));
    }

    if (surf >= h) return;            // nothing but air on this screen

    const top = Math.max(0, surf);
    const body = ctx.createLinearGradient(0, top, 0, h);
    body.addColorStop(0, css(colorAt(depthAt(top))));
    body.addColorStop(0.5, css(colorAt(depthAt(lerp(top, h, 0.5)))));
    body.addColorStop(1, css(colorAt(depthAt(h))));
    ctx.fillStyle = body;
    ctx.fillRect(0, top, w, h - top);

    drawShafts(ctx, env, surf);
    drawCaustics(ctx, env, surf);
    drawMotes(ctx, env, surf);
  }

  /* Sunlight coming down through the surface.

     A beam is not on a timer: its brightness is three slow waves added
     together, so the light gathers and fades where they happen to meet, the
     way it does on water. And no two beams share a clock — each one is given
     its own phases, its own rates, its own width and its own lean when the
     page opens, so the set never pulses as one. `shaft_randomness` is how far
     apart they are allowed to drift; at 0 they all move together again.

     The whole set is drawn small — a quarter of the size — on a canvas of its
     own, blurred there, and then blown up over the water. That is where the
     softness comes from and why it costs almost nothing: a blur over a quarter
     scale canvas is a sixteenth of the work, and the upscale smooths it again.
     `shaft_blur` is in pixels at the size they end up. */

  const beams = document.createElement('canvas');
  const beamCtx = beams.getContext('2d');
  const scratch = document.createElement('canvas');
  const scratchCtx = scratch.getContext('2d');
  const BEAM_SCALE = 4;
  let beamKey = '';
  let beamSeeds = [];

  /* Drawn once per beam, so the light wanders rather than jitters. */
  function seedBeams(count) {
    beamSeeds = [];
    for (let i = 0; i < count; i++) {
      beamSeeds.push({
        phase: [rand(0, Math.PI * 2), rand(0, Math.PI * 2), rand(0, Math.PI * 2)],
        rate: [rand(0.55, 1.6), rand(0.55, 1.6), rand(0.55, 1.6)],
        swayPhase: rand(0, Math.PI * 2),
        swayRate: rand(0.45, 1.7),
        swayAmount: rand(0.35, 1.5),
        lean: rand(-1, 1),
        width: rand(0.65, 1.5),
        bright: rand(0.55, 1.3),
        slot: rand(-0.34, 0.34)       // how far off its own share of the width
      });
    }
  }

  function paintBeams(env, surf) {
    const { t, w, h } = env;
    const bw = Math.max(1, Math.round(w / BEAM_SCALE));
    const bh = Math.max(1, Math.round(h / BEAM_SCALE));
    if (beams.width !== bw || beams.height !== bh) {
      beams.width = bw;
      beams.height = bh;
      scratch.width = bw;
      scratch.height = bh;
      beamKey = '';
    }

    const strength = Number(get('water.shafts', 0.55)) * quality();
    const count = Math.max(1, Math.round(Number(get('water.shaft_count', 5))));
    if (beamSeeds.length !== count) seedBeams(count);

    const width = Number(get('water.shaft_width', 0.07)) * bw;
    const soft = Math.max(1, Number(get('water.shaft_softness', 3.2)));
    const move = Number(get('water.movement', 1)) * motion();
    const wander = Number(get('water.shaft_wander', 0.09));
    const R = clamp(Number(get('water.shaft_randomness', 0.85)), 0, 1);
    const own = v => lerp(1, v, R);        // how much of its own way it goes
    const waves = get('water.shaft_interference', [0.21, 0.37, 0.09]);
    const f0 = Number(waves[0]) || 0.21;
    const f1 = Number(waves[1]) || 0.37;
    const f2 = Number(waves[2]) || 0.09;

    // a tenth of a second of the same light is not worth redrawing
    const key = `${Math.round(t * 10)}|${Math.round(surf)}|${strength}|${count}`;
    if (key === beamKey) return;
    beamKey = key;

    const top = surf / BEAM_SCALE;
    const fade = clamp(1 - Math.abs(surf) / (h * 0.8), 0, 1);

    scratchCtx.clearRect(0, 0, bw, bh);
    beamCtx.clearRect(0, 0, bw, bh);
    if (strength <= 0 || fade <= 0.01) return;
    scratchCtx.globalCompositeOperation = 'lighter';

    for (let i = 0; i < count; i++) {
      const s = beamSeeds[i];
      const seed = i * 1.37;
      // three waves meeting: sometimes they add up, sometimes they cancel
      const interference =
        (Math.sin(t * f0 * move * own(s.rate[0]) + seed * 2.1 + s.phase[0] * R) +
         Math.sin(t * f1 * move * own(s.rate[1]) + seed * 3.7 + s.phase[1] * R) +
         Math.sin(t * f2 * move * own(s.rate[2]) + seed * 1.1 + s.phase[2] * R)) / 3;
      const k = clamp(0.18 + 0.82 * (0.5 + 0.5 * interference), 0, 1.2) * own(s.bright);

      const sway = Math.sin(t * 0.17 * move * own(s.swayRate) + seed + s.swayPhase * R)
                 * bw * wander * own(s.swayAmount);
      const x = (bw / count) * (i + 0.5 + s.slot * R) + sway;
      const lean = lerp(Math.sin(seed) * 0.35, s.lean * 0.5, R);
      const reach = bh * 1.15;
      const spread0 = width * own(s.width);

      const light = scratchCtx.createLinearGradient(0, top, 0, top + reach);
      light.addColorStop(0, `rgba(198, 246, 255, ${0.075 * strength * fade * k})`);
      light.addColorStop(0.4, `rgba(190, 240, 255, ${0.034 * strength * fade * k})`);
      light.addColorStop(1, 'rgba(190, 240, 255, 0)');
      scratchCtx.fillStyle = light;

      // three passes, each wider and fainter: added up, a beam with no edge
      for (let pass = 0; pass < 3; pass++) {
        const spread = spread0 * (1 + pass * (soft - 1) * 0.5);
        scratchCtx.globalAlpha = 1 / (1 + pass * 1.4);
        scratchCtx.beginPath();
        scratchCtx.moveTo(x - spread * 0.4, top);
        scratchCtx.lineTo(x + spread * 0.4, top);
        scratchCtx.lineTo(x + spread * 1.5 + lean * reach, top + reach);
        scratchCtx.lineTo(x - spread * 1.5 + lean * reach, top + reach);
        scratchCtx.closePath();
        scratchCtx.fill();
      }
      scratchCtx.globalAlpha = 1;
    }

    // and the blur that takes the last edge off them
    const blur = Number(get('water.shaft_blur', 34)) / BEAM_SCALE;
    const canBlur = blur > 0.2 && 'filter' in beamCtx;
    if (canBlur) beamCtx.filter = `blur(${blur}px)`;
    beamCtx.drawImage(scratch, 0, 0);
    if (canBlur) beamCtx.filter = 'none';
  }

  function drawShafts(ctx, env, surf) {
    if (Number(get('water.shafts', 0.5)) * quality() <= 0) return;
    if (surf > env.h || surf < -env.h) return;
    paintBeams(env, surf);
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.drawImage(beams, 0, 0, env.w, env.h);
    ctx.restore();
  }

  /* The wandering light bands the surface throws onto everything under it.

     Each one is a filled strip with a gradient across it rather than a line,
     so its edges fade out instead of stopping. And each is laid down several
     times over — `caustic_passes` — wider and fainter every pass, which adds
     up to a band with no edge at all rather than one with a soft one.

     Each band also keeps its own phases and rates, so they wander past each
     other instead of sliding along in formation. `caustic_drift` is how far
     they are allowed to go their own way. */

  const BANDS = 9;
  let bandSeeds = [];

  function seedBands() {
    bandSeeds = [];
    for (let i = 0; i < BANDS; i++) {
      bandSeeds.push({
        phase: [rand(0, Math.PI * 2), rand(0, Math.PI * 2), rand(0, Math.PI * 2)],
        rate: [rand(0.6, 1.5), rand(0.55, 1.6), rand(0.7, 1.4)],
        amp: [rand(0.7, 1.35), rand(0.6, 1.4)],
        offset: rand(-0.5, 0.5),
        thick: rand(0.75, 1.3)
      });
    }
  }
  seedBands();

  function drawCaustics(ctx, env, surf) {
    const strength = Number(get('water.caustics', 0.4)) * quality();
    if (strength <= 0) return;

    const { t, w, h } = env;
    const scale = Math.max(0.2, Number(get('water.caustic_scale', 1)));
    const soft = Math.max(1, Number(get('water.caustic_softness', 6.5)));
    const move = Number(get('water.movement', 1)) * motion();
    const drift = clamp(Number(get('water.caustic_drift', 0.8)), 0, 1);
    const own = v => lerp(1, v, drift);
    // one pass is plenty on a machine that has already asked for less light
    const passes = state.lean
      ? 1
      : clamp(Math.round(Number(get('water.caustic_passes', 3))), 1, 4);

    ctx.save();
    ctx.globalCompositeOperation = 'lighter';

    for (let i = 0; i < BANDS; i++) {
      const s = bandSeeds[i];
      // the bands are not evenly spaced, or they read as stripes
      const spacing = (78 / scale) * (0.78 + 0.5 * Math.abs(Math.sin(i * 2.3)));
      const y = surf + 70 + i * spacing
              + Math.sin(i * 4.1) * 18 + s.offset * spacing * drift * 0.6;
      if (y < -140 || y > h + 140) continue;
      const near = clamp(1 - (y - surf) / (h * 1.4), 0, 1);
      if (near <= 0.02) continue;

      const thick = (2 + (i % 3) * 2.5) * soft * own(s.thick);
      const step = 60 / scale;
      const wave = x =>
          Math.sin(x / ((130 + i * 17) / scale)
                   + t * (0.5 + i * 0.05) * move * own(s.rate[0]) + i + s.phase[0] * drift)
            * 9 * own(s.amp[0])
        + Math.sin(x / ((55 + i * 9) / scale)
                   - t * 0.33 * move * own(s.rate[1]) + i * 1.7 + s.phase[1] * drift)
            * 5 * own(s.amp[1])
        + Math.sin(x / ((240 + i * 31) / scale)
                   + t * 0.14 * move * own(s.rate[2]) + s.phase[2] * drift)
            * 7 * drift;

      for (let pass = 0; pass < passes; pass++) {
        const spread = thick * (1 + pass * 1.7);
        const alpha = (0.075 * strength * near) / (1 + pass * 1.6);
        if (alpha <= 0.002) continue;

        ctx.beginPath();
        for (let x = -step; x <= w + step; x += step) ctx.lineTo(x, y + wave(x) - spread / 2);
        for (let x = w + step; x >= -step; x -= step) ctx.lineTo(x, y + wave(x) + spread / 2);
        ctx.closePath();

        // a falloff with no shoulder on it: nothing to read as an edge
        const band = ctx.createLinearGradient(0, y - spread / 2, 0, y + spread / 2);
        band.addColorStop(0, 'rgba(200, 246, 255, 0)');
        band.addColorStop(0.18, `rgba(200, 246, 255, ${alpha * 0.22})`);
        band.addColorStop(0.5, `rgba(200, 246, 255, ${alpha})`);
        band.addColorStop(0.82, `rgba(200, 246, 255, ${alpha * 0.22})`);
        band.addColorStop(1, 'rgba(200, 246, 255, 0)');
        ctx.fillStyle = band;
        ctx.fill();
      }
    }
    ctx.restore();
  }

  /* Specks of silt, so the water is never completely still. */
  function drawMotes(ctx, env, surf) {
    const alpha = Number(get('water.mote_opacity', 0.3));
    if (alpha <= 0) return;
    const { t, dt, w, h } = env;
    const move = Number(get('water.movement', 1)) * motion();

    ctx.save();
    ctx.fillStyle = `rgba(222, 248, 255, ${alpha})`;
    for (const m of motes) {
      m.y -= m.rise * dt * move * 0.25;
      m.x += Math.sin(t * 0.4 + m.phase) * m.drift * dt;
      if (m.y < -10) { m.y = h + 10; m.x = rand(0, w); }
      if (m.x < -10) m.x = w + 10;
      if (m.x > w + 10) m.x = -10;
      if (m.y < surf) continue;
      ctx.globalAlpha = alpha * clamp(1 - (m.y - surf) / (h * 1.6), 0.15, 1);
      ctx.beginPath();
      ctx.arc(m.x, m.y, m.r, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();
  }

  // ------------------------------------------------------------- surface --

  /* How far the line is lifted at a point by whatever has gone through it.

     A splash is a group of waves, not a ring: it leaves the point it was made
     at, travels out along the surface at `splash_speed`, and the water behind
     the front goes on rocking for a moment after it has passed. Nothing is
     lifted before the front arrives, which is what makes it read as travelling
     rather than as the whole line flexing at once. */
  function splashLift(x, t) {
    if (!splashes.length) return 0;

    const life = Math.max(0.3, Number(get('water.splash_life', 2.4)));
    const speed = Math.max(40, Number(get('water.splash_speed', 540)));
    const wave = Math.max(30, Number(get('water.splash_wave', 170)));
    const tall = Number(get('water.splash_height', 30));
    const k = (Math.PI * 2) / wave;

    let dy = 0;
    for (let i = splashes.length - 1; i >= 0; i--) {
      const s = splashes[i];
      const age = t - s.born;
      if (age > life) { splashes.splice(i, 1); continue; }

      const d = Math.abs(x - s.x);
      const front = speed * age;
      if (d > front) continue;                       // it hasn't reached here

      // dies away with time, with distance, and behind the front
      const fade = Math.pow(1 - age / life, 1.7);
      const spread = 1 / (1 + d / 300);
      const trail = Math.exp(-Math.pow((front - d) / (wave * 2.2), 2) * 0.55);

      dy -= Math.sin(k * (d - front) + s.seed) * tall * s.strength * fade * spread * trail;
    }
    return dy;
  }

  /* The line itself, drawn over everything so that the fish can break it.
     Several waves overlap — the far ones slow and faint, the near one crisp —
     which is what gives the surface its depth. `surface_layers` is how many. */
  function drawSurface(ctx, env) {
    const { t, w, h } = env;
    const surf = state.surfaceY;
    if (surf < -80 || surf > h + 80) { drawRipples(ctx, env); drawDrops(ctx, env); return; }

    const height = Number(get('water.wave_height', 9));
    const length = Math.max(40, Number(get('water.wave_length', 320)));
    const move = Number(get('water.movement', 1)) * motion();
    const foam = Number(get('water.foam', 0.5));
    const layers = Math.max(1, Math.round(Number(get('water.surface_layers', 3))
                                        - state.lean));

    // back to front: the last one drawn is the one the eye reads as the line
    for (let i = layers - 1; i >= 0; i--) {
      const far = layers > 1 ? i / (layers - 1) : 0;    // 1 is the farthest
      const amp = height * (1 - far * 0.45);
      const speed = 0.9 * move * (1 - far * 0.3);
      const drop = far * height * 1.5;
      const phase = i * 1.9;
      const strength = foam * (1 - far * 0.55);

      // the near layers take the most of a splash, the far ones a little
      const take = 1 - far * 0.55;

      const at = x => surf + drop
        + Math.sin(x / (length * (1 + far * 0.4)) * Math.PI * 2 + t * speed + phase) * amp
        + Math.sin(x / (length * 0.37) * Math.PI * 2 - t * speed * 1.5 + phase) * amp * 0.35
        + splashLift(x, t) * take;

      // a band of brighter water just under the front one
      ctx.save();
      if (i === 0) {
        ctx.beginPath();
        ctx.moveTo(0, at(0));
        for (let x = 0; x <= w; x += 20) ctx.lineTo(x, at(x));
        ctx.lineTo(w, at(w) + 30);
        ctx.lineTo(0, at(0) + 30);
        ctx.closePath();
        const band = ctx.createLinearGradient(0, surf + drop - amp, 0, surf + drop + 30);
        band.addColorStop(0, `rgba(222, 250, 255, ${0.26 * strength})`);
        band.addColorStop(1, 'rgba(222, 250, 255, 0)');
        ctx.fillStyle = band;
        ctx.fill();
      }

      // and the line itself. A splash is drawn at a finer step than the swell:
      // the wave group is short, and at 20px it would come out as corners.
      const step = splashes.length ? 7 : 20;
      ctx.beginPath();
      ctx.moveTo(0, at(0));
      for (let x = 0; x <= w; x += step) ctx.lineTo(x, at(x));
      ctx.strokeStyle = `rgba(233, 253, 255, ${0.5 * strength})`;
      ctx.lineWidth = 1.5 - far * 0.6;
      ctx.stroke();
      ctx.restore();
    }

    drawRipples(ctx, env);
    drawDrops(ctx, env);
  }

  /* What the splash threw up: droplets, falling back into the line they came
     out of. They are the part of a splash the eye actually reads as water. */
  function drawDrops(ctx, env) {
    if (!drops.length) return;
    const g = Number(get('water.splash_gravity', 1500));
    const { t, dt } = env;

    ctx.save();
    for (let i = drops.length - 1; i >= 0; i--) {
      const d = drops[i];
      const age = t - d.born;
      if (age > d.life) { drops.splice(i, 1); continue; }

      d.vy += g * dt;
      d.x += d.vx * dt;
      d.y += d.vy * dt;

      // back in the water, and gone
      if (d.vy > 0 && d.y > state.surfaceY + 2) { drops.splice(i, 1); continue; }

      const fade = Math.pow(1 - age / d.life, 0.7);
      // stretched along the way it is going, the way a droplet is
      const speed = Math.hypot(d.vx, d.vy);
      const long = clamp(speed / 900, 0, 1.4);

      ctx.save();
      ctx.translate(d.x, d.y);
      ctx.rotate(Math.atan2(d.vy, d.vx));
      ctx.fillStyle = `rgba(235, 252, 255, ${0.72 * fade})`;
      ctx.beginPath();
      ctx.ellipse(0, 0, d.r * (1 + long), d.r, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }
    ctx.restore();
  }

  /* A ring where something touched the water.

     It is round, because water does not know which way the screen is turned.
     And it is a wave rather than a circle: one front leaves the point it was
     made at and travels out at `ripple_speed`, with the crests behind it
     following at their own spacing, each one thinner and fainter than the one
     in front. Three things are doing the work:

       - the amplitude falls as 1/√r, which is what a ring spreading out over a
         surface does, on top of dying away with age;
       - every crest is drawn twice, bright on the near side and dark on the
         far side, because what you see of a ripple is the light bending
         through the slope of it rather than the water itself;
       - the front runs ahead of the rest: short waves travel slower than long
         ones on water, so the leading crest arrives alone and the fine ones
         gather up behind it.

     Capillary wrinkles ride just inside the front, which is the detail that
     stops it reading as a drawn circle. */
  function drawRipples(ctx, env) {
    if (!ripples.length) return;

    const life = Math.max(0.2, Number(get('water.ripple_life', 2.4)));
    const rings = Math.max(1, Math.round(Number(get('water.ripple_rings', 4))));
    const strength = Number(get('water.ripple_strength', 0.8));
    const speed = Math.max(20, Number(get('water.ripple_speed', 240)));
    const wave = Math.max(10, Number(get('water.ripple_wave', 34)));

    ctx.save();
    ctx.lineCap = 'round';

    /* A ring is round, but it is a ring on the water — so it is kept to the
       water. Without this the half of it above the line goes on expanding
       into the sky, which is the one thing that gives away that this is a
       circle being drawn rather than something happening on a surface. */
    const line = Math.max(0, state.surfaceY);
    if (line < env.h) {
      ctx.beginPath();
      ctx.rect(0, line, env.w, env.h - line);
      ctx.clip();
    }

    for (let i = ripples.length - 1; i >= 0; i--) {
      const r = ripples[i];
      const age = env.t - r.born;
      if (age >= life) { ripples.splice(i, 1); continue; }

      const t01 = age / life;
      const fade = Math.pow(1 - t01, 1.5);
      const front = speed * age * (0.55 + 0.45 * (1 - t01 * 0.5));

      for (let k = 0; k < rings; k++) {
        // the crests trail the front, the short ones further back
        const radius = front - k * wave * (1 + k * 0.22);
        if (radius <= 3) continue;

        const spread = 1 / Math.sqrt(Math.max(radius, 8) / 18);
        const amp = 0.5 * strength * r.strength * fade * spread
                  * Math.pow(0.68, k);
        if (amp <= 0.004) continue;

        const width = clamp(1 + amp * 3.4, 0.7, 3.4);

        // the dark side of the slope, just outside the crest
        ctx.strokeStyle = `rgba(3, 26, 34, ${Math.min(amp * 0.5, 0.3)})`;
        ctx.lineWidth = width * 1.25;
        ctx.beginPath();
        ctx.arc(r.x, r.y, radius + width * 0.9, 0, Math.PI * 2);
        ctx.stroke();

        // and the lit side of it
        ctx.strokeStyle = `rgba(228, 250, 255, ${Math.min(amp, 0.55)})`;
        ctx.lineWidth = width;
        ctx.beginPath();
        ctx.arc(r.x, r.y, radius, 0, Math.PI * 2);
        ctx.stroke();
      }

      /* The fine wrinkles that run ahead of a real ripple, just inside the
         front. They are drawn as one wobbling ring rather than a circle, so
         the leading edge is never a perfect curve. */
      const fineAmp = 0.22 * strength * r.strength * Math.pow(1 - t01, 2.2);
      if (fineAmp > 0.01 && front > 14) {
        ctx.strokeStyle = `rgba(228, 250, 255, ${fineAmp})`;
        ctx.lineWidth = 0.9;
        ctx.beginPath();
        const steps = 48;
        for (let s = 0; s <= steps; s++) {
          const a = (s / steps) * Math.PI * 2;
          const wobble = Math.sin(a * 7 + r.seed) * 1.6
                       + Math.sin(a * 13 - r.seed * 2) * 1.1;
          const rr = front - wave * 0.35 + wobble;
          const x = r.x + Math.cos(a) * rr;
          const y = r.y + Math.sin(a) * rr;
          if (s === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
        }
        ctx.stroke();
      }
    }
    ctx.restore();
  }

  // ---------------------------------------------------------------- loop --

  let clock = 0;
  let last = 0;
  const env = { t: 0, dt: 0, w: 0, h: 0 };

  /* If the machine can't keep up, the two most expensive things on the canvas
     — the sunbeams and the light bands — are quietly turned down, once, and
     stay down for the session. Nothing moves differently; there is just less
     light in the water. Set water.auto_quality to false to leave it alone. */
  let slowFor = 0;
  state.lean = 0;

  function watchTheFrameRate(dt) {
    if (state.lean >= 2 || get('water.auto_quality', true) === false) return;
    slowFor = dt > 1 / 30 ? slowFor + dt : Math.max(0, slowFor - dt * 2);
    if (slowFor > 2.5) {
      state.lean += 1;
      slowFor = 0;
      if (state.lean === 1) console.info(
        'The water is being drawn with less light, to keep the page smooth. ' +
        'Aquarium.config.water.auto_quality = false stops that.');
    }
  }

  // how much of a thing to draw, after any step-down
  const quality = () => state.lean === 0 ? 1 : (state.lean === 1 ? 0.5 : 0);

  function frame(now) {
    const dt = last ? Math.min((now - last) / 1000, 0.05) : 0.016;
    last = now;
    clock += dt;

    watchTheFrameRate(dt);

    env.t = clock;
    env.dt = dt;
    env.w = view.w;
    env.h = view.h;

    // where the waterline is on screen right now
    climb();
    state.surfacePageY = resting;
    state.surfaceY = state.broken && (rise || risen)
      ? resting - window.scrollY
      : view.h + 80;

    ctx.clearRect(0, 0, view.w, view.h);
    for (const layer of layers) layer.draw(ctx, env);

    requestAnimationFrame(frame);
  }

  // --------------------------------------------------------------- input --

  /* A click anywhere on the page is a click on the water: it rings, and the
     fish comes over. Clicks on something you can actually press are left
     alone, apart from the bowl, which does its own thing with them. */
  document.addEventListener('click', event => {
    if (document.body.classList.contains('detail-open')) return;
    // the bowl answers its own taps; everything else you can press is doing
    // something of its own
    if (event.target.closest('a, button, input, textarea, select, summary, label, .settings')) return;

    state.lastClick = { x: event.clientX, y: event.clientY, at: clock };
    if (state.broken && event.clientY > state.surfaceY) {
      scene.ripple(event.clientX, event.clientY, 1);
    }
  }, true);

  window.addEventListener('pointermove', event => {
    const p = state.pointer;
    p.x = event.clientX;
    p.y = event.clientY;
    p.moved = clock;
    p.inside = true;
  }, { passive: true });

  window.addEventListener('pointerleave', () => { state.pointer.inside = false; });

  window.addEventListener('resize', () => { resize(); remeasureSurface(); });
  window.addEventListener('scroll', remeasureSurface, { passive: true });

  // ----------------------------------------------------------------- go --

  resize();
  remeasureSurface();
  scene.add(10, drawWater);
  scene.add(90, drawSurface);
  requestAnimationFrame(frame);

  // So the other modules can measure the line again after a reset.
  Aquarium.remeasureSurface = remeasureSurface;
  Aquarium.clock = () => clock;

})();

/* src/assets/js/08-shoal.js */
/* The little fish he swims among.

   They are drawn rather than sprited: a body, a tail, and a wave through both,
   which at this size reads as a fish and costs almost nothing. Their colour is
   mixed into the water around them — `blend` in aquarium.yaml, at 1 they
   disappear entirely — so that the one orange fish is the only thing on the
   page that holds the eye.

   They keep loose company with each other, drift up or down with the scroll
   according to how far away they are, and scatter when he comes past. */

(() => {
  'use strict';

  const { get, range, clamp, lerp, rand, pick, motion, mix, css, colorAt, depthAt } = Aquarium;
  const state = Aquarium.state;
  const scene = Aquarium.scene;
  if (!scene) return;

  let shoal = [];
  let lastScroll = window.scrollY;

  function view() { return scene.view; }

  function spawn(fresh) {
    const [small, big] = range('shoal.size', 9, 26);
    const [slow, quick] = range('shoal.speed', 14, 46);
    const v = view();
    const z = Math.random();                       // 0 near, 1 far
    return {
      x: fresh ? rand(-60, v.w + 60) : (Math.random() < 0.5 ? -60 : v.w + 60),
      y: rand(Math.max(0, state.surfaceY) + 30, v.h + 120),
      z,
      len: lerp(big, small, z),
      speed: lerp(quick, slow, z) * rand(0.8, 1.2),
      dir: Math.random() < 0.5 ? -1 : 1,
      drift: rand(-0.25, 0.25),
      phase: rand(0, Math.PI * 2),
      beat: rand(2.4, 4.2),
      turn: 0
    };
  }

  function restock() {
    const want = Math.max(0, Math.round(Number(get('shoal.count', 34))));
    while (shoal.length > want) shoal.pop();
    while (shoal.length < want) shoal.push(spawn(true));
  }

  function draw(ctx, env) {
    if (!state.broken && state.pour <= 0) return;
    restock();

    const { t, dt, w, h } = env;
    const blend = clamp(Number(get('shoal.blend', 0.78)), 0, 1);
    const alpha = Number(get('shoal.opacity', 0.5));
    const own = get('shoal.color', '#9fe3ef');
    const spread = Number(get('shoal.depth_spread', 0.9));
    const schooling = Number(get('shoal.schooling', 0.45));
    const shy = Number(get('shoal.shy', 90));
    const wiggle = Number(get('shoal.wiggle', 1.1));
    const surf = state.surfaceY;

    // the scroll carries them, the far ones less than the near ones
    const scrolled = window.scrollY - lastScroll;
    lastScroll = window.scrollY;

    // the shoal's own centre, for the ones that want company
    let cx = 0, cy = 0;
    for (const f of shoal) { cx += f.x; cy += f.y; }
    cx /= (shoal.length || 1);
    cy /= (shoal.length || 1);

    const koi = state.fish;

    ctx.save();
    for (const f of shoal) {
      f.y -= scrolled * lerp(1, 0.35, f.z * spread);

      // wander
      f.turn += rand(-1, 1) * dt * 0.8;
      f.turn = clamp(f.turn, -0.5, 0.5);
      f.y += (f.drift + f.turn * 0.4) * f.speed * dt * motion();
      if (schooling > 0) {
        f.x += (cx - f.x) * schooling * 0.04 * dt;
        f.y += (cy - f.y) * schooling * 0.12 * dt;
      }

      // give him room
      if (koi && koi.x !== undefined) {
        const dx = f.x - koi.x, dy = f.y - koi.y;
        const dist = Math.hypot(dx, dy);
        if (dist < shy && dist > 0.01) {
          const push = (1 - dist / shy) * 180 * dt;
          f.x += (dx / dist) * push;
          f.y += (dy / dist) * push;
          f.dir = dx >= 0 ? 1 : -1;
        }
      }

      f.x += f.speed * f.dir * dt * motion();

      // the water is the whole screen; they wrap round it
      if (f.x < -120) { f.x = w + 110; f.y = rand(Math.max(0, surf) + 40, h); }
      if (f.x > w + 120) { f.x = -110; f.y = rand(Math.max(0, surf) + 40, h); }
      const floor = h + 140;
      const ceiling = Math.max(0, surf) + 24;
      if (f.y > floor) f.y = ceiling + 20;
      if (f.y < ceiling) f.y = Math.min(floor - 20, ceiling + rand(10, 120));

      if (f.y < surf + 6) continue;        // not above the waterline

      // their colour is mostly the water they are in
      const water = colorAt(depthAt(f.y));
      const body = mix(own, water, blend);
      const fade = alpha * lerp(1, 0.35, f.z * spread);

      const beat = Math.sin(t * f.beat + f.phase) * wiggle;
      const len = f.len;
      const tall = len * 0.42;

      ctx.save();
      ctx.translate(f.x, f.y);
      ctx.scale(f.dir, 1);
      ctx.rotate(beat * 0.06);
      ctx.globalAlpha = clamp(fade, 0, 1);
      ctx.fillStyle = css(body);

      // body and tail, drawn twice: once in the colour of the water they are
      // in, and once as a breath of their own colour added on top, so that
      // they stay just visible when the water goes dark
      for (let pass = 0; pass < 2; pass++) {
        if (pass === 1) {
          ctx.globalCompositeOperation = 'lighter';
          ctx.globalAlpha = clamp(fade, 0, 1) * 0.3 * (1 - blend * 0.5);
          ctx.fillStyle = css(Aquarium.rgb(own));
        }
        ctx.beginPath();
        ctx.ellipse(0, 0, len * 0.5, tall * 0.5, 0, 0, Math.PI * 2);
        ctx.fill();

        ctx.beginPath();
        ctx.moveTo(-len * 0.42, 0);
        ctx.lineTo(-len * 0.72, -tall * (0.5 + beat * 0.1));
        ctx.lineTo(-len * 0.72, tall * (0.5 - beat * 0.1));
        ctx.closePath();
        ctx.fill();
      }

      ctx.restore();
    }
    ctx.restore();
  }

  window.addEventListener('resize', () => { shoal = []; });

  scene.add(30, draw);

})();

/* src/assets/js/09-fish.js */
/* Him.

   The artwork is a flat drawing seen from the side, so the body is bent rather
   than jointed: the sprite is rasterised once, then redrawn every frame as a
   row of thin vertical strips, each nudged up or down by a wave travelling
   from nose to tail. The head barely moves, the tail swings hardest, and the
   whole shape flexes the way a fish does.

   He has four lives, in order:

       bowl     turning circles behind the glass, with nowhere to go. A tap
                brings him up for a look; another puts his nose through the
                surface
       leap     the tap that breaks the glass throws him into the air, where
                he turns over once or twice and doubles in size on the way down
       free     out in the water, following the cursor, circling whatever you
                hover, and dashing to wherever you click. The water is wider
                than the window: he can carry on out past the edge of it and
                come back, and he can turn right over, nose over tail, as he
                goes
       jump     out of the water altogether — of his own accord every so
                often, or after a click in the sky above the waterline. He
                arcs, turns over if he feels like it, and comes back down with
                a splash

   Everything he does comes from the `fish` block of src/content/aquarium.yaml.
   Replace src/assets/svg/koi_fish.svg to change the fish; the only settings
   tied to the drawing are `faces`, which says which way its nose points, and
   `mouth`, which is where the bubbles come from. */

(() => {
  'use strict';

  const { get, range, clamp, lerp, rand, pick, motion, css, colorAt, depthAt } = Aquarium;
  const state = Aquarium.state;
  const scene = Aquarium.scene;
  if (!scene) return;

  // --------------------------------------------------------- the sprites --

  /* Two drawings, one for each way he goes: `fish-sprite-left` and
     `fish-sprite-right`, both inlined into the page by the build.

     He is no longer one drawing held up to a mirror. When he comes about, the
     drawing he is wearing is squashed down through nothing and the other one
     opens out on the far side of it — so the turn is the same movement it
     always was, but what you see afterwards is a drawing made to face that
     way rather than a flipped copy of the other one.

     Each file is trimmed to its ink with a transparent background, so there is
     nothing to crop here and nothing to read back off a canvas. */

  const sheets = { left: null, right: null };
  const shades = { left: null, right: null };
  const shape = { left: 0.46, right: 0.46 };   // height ÷ length, per drawing
  let ready = false;

  function loadSprites() {
    let settled = 0;

    const finish = () => {
      if (++settled < 2) return;
      // one drawing missing is not worth a fishless page: the other does both
      if (!sheets.left && sheets.right) {
        sheets.left = sheets.right; shades.left = shades.right; shape.left = shape.right;
      }
      if (!sheets.right && sheets.left) {
        sheets.right = sheets.left; shades.right = shades.left; shape.right = shape.left;
      }
      ready = !!sheets.right;
    };

    for (const side of ['left', 'right']) {
      const img = document.getElementById('fish-sprite-' + side);
      if (!img) { finish(); continue; }

      const take = () => {
        const w = img.naturalWidth || img.width;
        const h = img.naturalHeight || img.height;
        if (w && h) {
          const c = document.createElement('canvas');
          c.width = w; c.height = h;
          c.getContext('2d').drawImage(img, 0, 0, w, h);
          sheets[side] = c;
          shape[side] = h / w;
          shades[side] = silhouette(c);
        }
        finish();
      };

      if (img.complete && img.naturalWidth) take();
      else {
        img.addEventListener('load', take, { once: true });
        img.addEventListener('error', finish, { once: true });
      }
    }
  }

  /* Which drawing he is wearing this frame. `flip` is the width he is drawn
     at, signed: it eases from one side to the other and the swap happens as it
     passes through zero, which is the middle of the turn. */
  function sideNow() {
    return fish.flip >= 0 ? 'right' : 'left';
  }

  /* How tall he is for his length, in the drawing he is wearing. */
  function bodyRatio() {
    return shape[sideNow()] || 0.46;
  }

  /* A black copy of him, softened once here rather than on every frame, so
     that his shadow costs one more blit and not a filter. */
  function silhouette(src) {
    const c = document.createElement('canvas');
    c.width = src.width; c.height = src.height;
    const g = c.getContext('2d');
    g.drawImage(src, 0, 0);
    g.globalCompositeOperation = 'source-in';
    g.fillStyle = '#000';
    g.fillRect(0, 0, c.width, c.height);

    if (!('filter' in g)) return c;
    const soft = document.createElement('canvas');
    soft.width = c.width; soft.height = c.height;
    const sg = soft.getContext('2d');
    sg.filter = `blur(${Math.max(2, c.width * 0.02)}px)`;
    sg.drawImage(c, 0, 0);
    return soft;
  }

  // ------------------------------------------------------------- the fish --

  const fish = {
    x: 0, y: 0,
    vx: -20, vy: 0,
    facing: -1,            // -1 nose left, +1 nose right
    flip: 1,               // the width he is drawn at, while turning over
    placed: false,
    phase: 0,
    mode: 'bowl',          // bowl | leap | free | jump
    grow: 0,               // 0 the size he is in the bowl, 1 the size he ends
    spin: 0,               // how far round he is, mid-leap
    spinRate: 0,
    hold: null,            // somewhere he has been startled to
    target: null,
    nextThink: 0,
    dash: null,
    nextBubble: 2,
    now: 0,                // the scene clock, for anything drawing itself
    roll: null,            // a full turn, nose over tail, under way
    nextRoll: 6,
    nextJump: 7,
    wantJump: null,        // a click in the sky he is working his way up to
    outside: 0,            // how long he has been off the edge of the window
    dive: null,            // heading for the bottom while the water comes up
    leap: null,            // the way out of the bowl: up, hang, turn, fall
    unwind: null,          // levelling out after the dive
    lastBreak: -9          // when he last came through the surface
  };
  state.fish = fish;

  const bubbles = [];

  /* How long he is, in pixels. He leaves the bowl at `size_bowl` and arrives in
     the water `grow_to` times that, growing on the way down. On a narrow screen
     he is held to a share of it, so a phone doesn't get a fish wider than the
     page. */
  function length() {
    const small = Number(get('fish.size_bowl', 140));
    const big = small * Number(get('fish.grow_to', 2));
    const want = lerp(small, big, clamp(fish.grow, 0, 1));
    const room = scene.view.w * Number(get('fish.max_share', 0.5));
    return Math.max(60, Math.min(want, room));
  }

  // ------------------------------------------------------------- steering --

  /* The water inside the glass. `air` lets him up into the space above it,
     which is what a breach is. */
  function bowlBox(air) {
    const b = state.bowl;
    if (!b) return null;
    const level = Number(get('bowl.water_level', 0.8));
    const len = length();
    // far enough in that his nose and tail stay behind the glass
    const inset = Math.max(b.w * 0.16, len * 0.55);
    const waterline = b.y + b.h * (1 - level);
    const bottom = b.y + b.h * (1 - Number(get('bowl.gravel_depth', 0.16)) * 0.8);
    return {
      left: b.x + inset,
      right: b.x + b.w - inset,
      top: (air ? b.y + b.h * 0.06 : waterline + b.h * 0.06) + len * 0.1,
      bottom: bottom - len * 0.2,
      waterline
    };
  }

  /* The water you can see. This is where he decides to go. */
  function visibleBox() {
    const v = scene.view;
    const pad = length() * 0.5;
    return {
      left: pad * 0.5,
      right: v.w - pad * 0.5,
      top: Math.max(state.surfaceY, 0) + pad * 0.5,
      bottom: v.h - pad * 0.4
    };
  }

  /* And how far the water goes. The window is not the edge of it: he may carry
     on out past the side or the bottom by `off_frame` of his own lengths,
     which is what makes the water feel wider than the screen. The surface is
     the one wall he cannot swim through — going above it is a jump. */
  function limitBox() {
    const v = scene.view;
    const len = length();
    const out = Math.max(0, Number(get('fish.off_frame', 1.4))) * len;
    return {
      // He is allowed right up under the line rather than held a body's depth
      // below it: a click just under the surface is a place he can reach, and
      // his back breaking through is a splash, not a mistake.
      top: Math.max(state.surfaceY + len * Number(get('fish.surface_gap', 0.12)),
                    -out * 0.6),
      left: -out,
      right: v.w + out,
      bottom: v.h + out * 0.5
    };
  }

  /* Where he is held, and where he aims. In the bowl they are the same thing. */
  function box() {
    if (fish.mode !== 'bowl') return limitBox();
    return bowlBox(!!(fish.hold && fish.hold.air)) || limitBox();
  }

  function roam() {
    if (fish.mode !== 'bowl') return visibleBox();
    return bowlBox(!!(fish.hold && fish.hold.air)) || visibleBox();
  }

  function newTarget(t) {
    const b = roam();
    if (!b || b.right <= b.left || b.bottom <= b.top) return;

    let x = rand(b.left, b.right);
    const y = rand(b.top, b.bottom);
    let out = false;

    // now and then he simply carries on out of the frame, and comes back
    if (fish.mode === 'free' && Math.random() < Number(get('fish.off_frame_chance', 0.18))) {
      const lim = limitBox();
      x = Math.random() < 0.5 ? rand(lim.left, b.left) : rand(b.right, lim.right);
      out = true;
    }

    fish.target = { x, y, out };
    const [lo, hi] = range('fish.wander_range', 1.4, 3.6);
    // somewhere off the edge is a long way at a cruise, so once he has decided
    // to go he keeps going: he does not change his mind halfway out there
    fish.nextThink = t + (out ? Math.max(hi, 2.5) * 2 : rand(lo, hi));
  }

  /* A click: he comes about on the spot and goes straight there. If that means
     doubling back on himself he sometimes turns right over instead of simply
     facing the other way. */
  function dashTo(x, y, t) {
    if (fish.mode === 'leap' || fish.mode === 'jump' || fish.dive) return;
    const back = (x >= fish.x ? 1 : -1) !== fish.facing;
    fish.dash = { x, y, until: t + Math.max(0.2, Number(get('fish.dash_time', 1.4))) };
    if (back && fish.mode === 'free'
        && Math.random() < Number(get('fish.roll_on_dash', 0.4)) && startRoll(t)) {
      // a roll keeps him pointing the way he was until he comes round
      return;
    }
    fish.facing = x >= fish.x ? 1 : -1;
    // the turn itself is quick rather than instant; starting it near zero is
    // what makes it read as a fish coming about rather than a drawing swapping
    fish.flip = fish.facing * 0.06;
  }

  // ------------------------------------------------ turning right over --

  /* A full 360 in the water: nose over tail, once round, and on he goes. It is
     an angle added to however he is already held, so he keeps swimming — he
     does not stop to do it. */
  function startRoll(t, dir) {
    if (get('fish.roll', true) === false) return false;
    if (fish.roll || fish.mode !== 'free') return false;
    fish.roll = {
      at: t,
      dur: Math.max(0.2, Number(get('fish.roll_time', 0.95))),
      dir: dir || (Math.random() < 0.5 ? -1 : 1)
    };
    const [lo, hi] = range('fish.roll_every', 7, 18);
    fish.nextRoll = t + rand(lo, hi);
    return true;
  }

  function rollAngle() {
    if (!fish.roll) return 0;
    const p = clamp((fish.now - fish.roll.at) / fish.roll.dur, 0, 1);
    const eased = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
    return eased * Math.PI * 2 * fish.roll.dir;
  }

  // ----------------------------------------------------- out of the water --

  /* Near enough the line, and out in open water, to leave it. */
  function canJump() {
    if (fish.mode !== 'free' || get('fish.jump', true) === false) return false;
    if (fish.dive || state.pour < 0.9) return false;
    const v = scene.view;
    const surf = state.surfaceY;
    if (surf < -v.h * 0.15 || surf > v.h) return false;      // the line is off screen
    return (fish.y - surf) < Number(get('fish.jump_near_surface', 320));
  }

  /* On the cursor's tail: it is in the window and has moved lately. */
  function following(t) {
    const p = state.pointer;
    return get('fish.follow', true) !== false && p.inside
      && (t - p.moved) < Number(get('fish.idle_after', 2.5));
  }

  /* Out he goes. With somewhere to aim for he is thrown exactly hard enough to
     get there; left to himself he gives it `jump_power` and sees what happens.
     Either way he comes down where the water is, not out through the side. */
  function jump(t, aim) {
    const g = Math.max(100, Number(get('fish.jump_gravity', 1400)));
    const surf = state.surfaceY;
    const deep = Math.max(0, fish.y - surf);
    const v = scene.view;

    let power = Number(get('fish.jump_power', 620));
    let vx = fish.vx * 0.8 + rand(-120, 120);

    if (aim) {
      const climb = deep + Math.max(30, surf - aim.y) + length() * 0.5;
      power = clamp(Math.sqrt(2 * g * climb), 220,
                    Number(get('fish.jump_power_max', 1500)));
      const air = (power + Math.sqrt(Math.max(0, power * power - 2 * g * deep))) / g;
      vx = (aim.x - fish.x) / Math.max(0.25, air);
    }

    // he has to clear the surface, or it is not a jump
    if (power * power <= 2 * g * deep * 1.05) power = Math.sqrt(2 * g * deep) * 1.25 + 220;

    // and he does not jump out through the edge of the window
    if (fish.x < v.w * 0.1 && vx < 0) vx = Math.abs(vx);
    if (fish.x > v.w * 0.9 && vx > 0) vx = -Math.abs(vx);

    fish.mode = 'jump';
    fish.dash = null;
    fish.hold = null;
    fish.roll = null;
    fish.wantJump = null;
    fish.spin = 0;
    fish.jumpAt = t;
    fish.vy = -power;
    fish.vx = clamp(vx, -1300, 1300);
    fish.facing = fish.vx >= 0 ? 1 : -1;
    fish.flip = fish.facing;

    const air = (power + Math.sqrt(Math.max(0, power * power - 2 * g * deep))) / g;
    const [few, many] = range('fish.jump_flips', 0, 1);
    const turns = Math.round(rand(few, many));
    fish.spinRate = turns
      ? (turns * Math.PI * 2) / Math.max(0.25, air) * (fish.vx >= 0 ? 1 : -1)
      : 0;

    // leaving the water throws it about, the same as coming back does
    breakSurface(t, 0.75);
    scheduleJump(t);
  }

  /* Going through the line, either way. The water answers with a splash that
     runs out along the surface, a ring on it, and the sound of it. */
  function breakSurface(t, strength) {
    fish.lastBreak = t;
    const s = clamp(strength, 0.1, 2.4);
    Portfolio.sound.splash(clamp(s, 0.2, 1.2));
    if (scene.splash) scene.splash(fish.x, s, fish.vy >= 0 ? 1 : -1);
    scene.ripple(fish.x, state.surfaceY, s);
  }

  function scheduleJump(t) {
    const [lo, hi] = range('fish.jump_every', 8, 20);
    fish.nextJump = t + rand(lo, hi);
  }

  /* Mid-air, out in the open: gravity, whatever turn he started, and the line
     coming back up at him. */
  function arc(t, dt) {
    fish.vy += Number(get('fish.jump_gravity', 1400)) * dt;
    fish.x += fish.vx * dt;
    fish.y += fish.vy * dt;
    fish.spin += fish.spinRate * dt;

    const down = fish.vy > 0 && fish.y >= state.surfaceY;
    // and if the line has moved out from under him, he is back in after this
    const lost = (t - fish.jumpAt) > 4;
    if (down || lost) splashDown(t);
  }

  function splashDown(t) {
    const hit = clamp(Math.abs(fish.vy) / 700, 0.5, 1.9);
    fish.mode = 'free';
    fish.spin = 0;
    fish.spinRate = 0;
    fish.grow = 1;
    fish.vy = Math.abs(fish.vy) * 0.4;
    fish.vx *= 0.7;
    fish.y = Math.max(fish.y, state.surfaceY + 2);
    breakSurface(t, hit);
    newTarget(t);
  }

  // ------------------------------------------------- what a tap does to him --

  /* Every tap but the last. He comes up to look, and then puts his nose out. */
  function startle(step, final, t) {
    const b = bowlBox(true);
    if (!b) return;
    const hold = Number(get('glass.rise_hold', 1.4));
    const breach = Number(get('glass.breach', 0.35)) * length() * bodyRatio();
    const nose = step >= final - 1;      // the tap before the one that breaks it

    // a fish puts his nose out in the middle, where there is room for it
    const middle = (b.left + b.right) / 2;
    fish.hold = {
      x: nose ? middle + rand(-14, 14) : clamp(fish.x + rand(-40, 40), b.left, b.right),
      y: nose ? b.waterline - breach : b.waterline + length() * bodyRatio() * 0.45,
      air: nose,
      until: t + hold
    };
    fish.target = null;
  }

  // ------------------------------------------------------------- bubbles --

  function breathe(t, dt) {
    if (get('fish.bubbles', true) === false) return;

    if (t > fish.nextBubble) {
      const [lo, hi] = range('fish.bubble_every', 1.6, 5);
      fish.nextBubble = t + rand(lo, hi);
      if (fish.mode === 'bowl' || fish.mode === 'free') {
        const [few, many] = range('fish.bubble_count', 1, 4);
        const n = Math.round(rand(few, many));
        const [small, big] = range('fish.bubble_size', 2, 6);
        const m = mouth();
        for (let i = 0; i < n; i++) {
          bubbles.push({
            x: m.x + rand(-4, 4),
            y: m.y + rand(-4, 4),
            r: rand(small, big),
            phase: rand(0, Math.PI * 2),
            born: t,
            life: Number(get('fish.bubble_life', 4)) * rand(0.7, 1.2)
          });
        }
        if (n > 1) Portfolio.sound.bubble(0.6);
      }
    }

    const rise = Number(get('fish.bubble_rise', 42));
    const wobble = Number(get('fish.bubble_wobble', 14));
    for (let i = bubbles.length - 1; i >= 0; i--) {
      const b = bubbles[i];
      const age = t - b.born;
      b.y -= rise * dt * (0.7 + b.r / 8) * motion();
      b.x += Math.sin(t * 2.2 + b.phase) * wobble * dt;
      const ceiling = state.broken ? state.surfaceY : (state.bowl
        ? state.bowl.y + state.bowl.h * (1 - Number(get('bowl.water_level', 0.8)))
        : 0);
      if (age > b.life || b.y < ceiling + b.r) bubbles.splice(i, 1);
    }
  }

  /* Where his mouth is right now, in screen pixels — the bubbles start here.
     `mouth` in the YAML is a point on the left-facing drawing, across and
     down; on the right-facing one it is the same point read from the other
     end, because that drawing is the fish the other way round and not a
     mirror of this one. */
  function mouth() {
    const m = get('fish.mouth', [0.03, 0.46]);
    const len = length();
    const h = len * bodyRatio();
    const across = sideNow() === 'left' ? Number(m[0]) : 1 - Number(m[0]);
    const lx = (across - 0.5) * len;
    const ly = (Number(m[1]) - 0.5) * h;
    const rot = rotation();
    return {
      x: fish.x + lx * Math.cos(rot) - ly * Math.sin(rot),
      y: fish.y + lx * Math.sin(rot) + ly * Math.cos(rot)
    };
  }

  /* How far round the drawing is turned.

     The sprite is a side view and is mirrored left and right, so the angle is
     measured from whichever way his nose is pointing — which is why the sign
     follows `facing`.

     In the air he is held nose-first along his own arc, plus whatever flips he
     is doing. In the water he tips nose-up or nose-down by `pitch`, plus a
     roll if one is under way — and a roll is a whole turn, so this is where
     the 360 comes from. */
  function rotation() {
    if (fish.mode === 'leap') return fish.spin;

    // On the way down after the splash, and while he waits at the bottom for
    // the water, he is pointed straight down whatever he is doing.
    const noseDown = (Math.PI / 2) * (fish.facing >= 0 ? 1 : -1);
    if (fish.dive) {
      // unless he has started coming round to level for the end of it
      const lv = fish.dive.level;
      if (!lv) return noseDown;
      const k = clamp((fish.now - lv.at) / lv.dur, 0, 1);
      return lerp(noseDown, swimRotation(), k * k * (3 - 2 * k));
    }

    const raw = swimRotation();
    // and once he is let go he comes round to level, rather than snapping
    const u = fish.unwind;
    if (u) {
      const k = clamp((fish.now - u.at) / u.dur, 0, 1);
      if (k >= 1) fish.unwind = null;
      else return lerp(u.from, raw, k * k * (3 - 2 * k));
    }
    return raw;
  }

  function swimRotation() {
    const speed = Math.hypot(fish.vx, fish.vy);
    const sign = fish.facing >= 0 ? 1 : -1;

    if (fish.mode === 'jump') {
      const along = speed < 1 ? 0 : Math.atan2(fish.vy, Math.max(Math.abs(fish.vx), 1)) * sign;
      return clamp(along, -1.35, 1.35) + fish.spin;
    }

    const roll = rollAngle();
    if (speed < 1) return roll;
    const k = Number(get('fish.pitch', 0.45));
    const pitch = Math.atan2(fish.vy, Math.max(Math.abs(fish.vx), 30)) * k;
    return clamp(pitch, -1.1, 1.1) * sign + roll;
  }

  // -------------------------------------------------------- what's hovered --

  let hovered = null;

  function targets() {
    return String(get('fish.circle_targets', '.entry'));
  }

  document.addEventListener('pointerover', event => {
    if (get('fish.circle', true) === false) return;
    let el = null;
    try { el = event.target.closest(targets()); } catch (err) { return; }
    if (el) hovered = el;
  }, true);

  document.addEventListener('pointerout', event => {
    if (!hovered) return;
    const to = event.relatedTarget;
    if (!to || !hovered.contains(to)) hovered = null;
  }, true);

  /* The ring he swims around whatever the cursor is on: the thing's own box,
     pushed out by `circle_margin`, so he passes outside it rather than through
     it — but never wider than a couple of `circle_radius`, or a tall row would
     have him circling the whole screen. It is centred on the part of the thing
     you can actually see, so a half-scrolled row is still circled on screen. */
  function orbit() {
    if (!hovered || !hovered.isConnected) { hovered = null; return null; }
    const v = scene.view;
    const r = hovered.getBoundingClientRect();
    if (!r.width || r.bottom < 0 || r.top > v.h) return null;

    const margin = Number(get('fish.circle_margin', 40));
    const radius = Number(get('fish.circle_radius', 150));
    const left = Math.max(r.left, 0), right = Math.min(r.right, v.w);
    const top = Math.max(r.top, 0), bottom = Math.min(r.bottom, v.h);

    return {
      cx: (left + right) / 2,
      cy: (top + bottom) / 2,
      rx: clamp(Math.min(r.width / 2 + margin, radius * 1.8), radius * 0.5, v.w * 0.42),
      ry: clamp(Math.min(r.height / 2 + margin, radius * 1.4), radius * 0.35, v.h * 0.38)
    };
  }

  // -------------------------------------------------------------- update --

  function update(t, dt) {
    fish.now = t;

    // the first frame the bowl has been measured, he goes in it
    if (!fish.placed && (state.bowl || state.broken)) {
      fish.placed = true;
      if (!state.broken) Aquarium.fish.reset();
    }

    if (fish.roll && t > fish.roll.at + fish.roll.dur) fish.roll = null;

    /* A click anywhere is a place to be. Above the waterline it is somewhere
       he has to leave the water to reach: if he is near enough the line he
       goes straight for it, and if he isn't he swims up and jumps when he
       gets there. */
    const click = state.lastClick;
    if (click && click.at > (fish.lastClickSeen || -1)) {
      fish.lastClickSeen = click.at;
      const sky = state.broken && click.y < state.surfaceY - 6
               && get('fish.jump_at_clicks', true) !== false;
      if (sky && canJump()) {
        jump(t, { x: click.x, y: click.y });
      } else if (sky && fish.mode === 'free') {
        fish.wantJump = { x: click.x, y: click.y, until: t + 3 };
        dashTo(click.x, state.surfaceY + length() * 0.4, t);
      } else {
        dashTo(click.x, click.y, t);
      }
    }

    // the one he was working his way up to, now that he is up there
    if (fish.wantJump) {
      if (t > fish.wantJump.until) fish.wantJump = null;
      else if (canJump()) jump(t, fish.wantJump);
    }

    // and one of his own, every so often, when he has nothing else on
    if (t > fish.nextJump) {
      if (canJump() && !fish.dash && !hovered && !following(t)) jump(t, null);
      else if (fish.mode === 'free') fish.nextJump = t + 2;
      else scheduleJump(t);
    }

    // a turn of his own, for no reason at all
    if (t > fish.nextRoll && fish.mode === 'free' && !fish.dash && !fish.dive) startRoll(t);

    if (fish.mode === 'leap') fly(t, dt);
    else if (fish.mode === 'jump') arc(t, dt);
    else swim(t, dt);

    // how long he has been off the edge of the window. Left to his own
    // devices out there, he turns round and comes back in.
    const v = scene.view;
    const away = fish.x < -4 || fish.x > v.w + 4 || fish.y > v.h + 4;
    fish.outside = away ? fish.outside + dt : 0;
    if (fish.outside > Number(get('fish.off_frame_return', 2.6))) {
      fish.outside = 0;
      if (fish.mode === 'free' && !fish.dash) {
        const inner = visibleBox();
        fish.target = {
          x: clamp(fish.x, inner.left + 40, inner.right - 40),
          y: rand(inner.top, inner.bottom)
        };
        fish.nextThink = t + 2;
      }
    }

    // the body wave runs faster the harder he is working
    const speed = Math.hypot(fish.vx, fish.vy);
    const base = Number(get('fish.stroke_rate', 1.5));
    const extra = Number(get('fish.stroke_speedup', 0.5));
    fish.phase += dt * Math.PI * 2 * (base + (speed / 220) * base * extra);

    // turning over: the drawing is squashed through zero rather than snapped,
    // which reads as the fish swinging round towards you. A dash turns harder.
    const turnTime = Math.max(0.03, Number(fish.dash
      ? get('fish.dash_turn', 0.07)
      : get('fish.turn_time', 0.16)));
    fish.flip += (fish.facing - fish.flip) * Math.min(1, dt / turnTime * 1.6);

    breathe(t, dt);
  }

  /* Out of the bowl. Three parts, on a clock that starts at the break:

     up     to the top of the screen, slowing into it, in `leap_rise` seconds;
     hang   held there until `leap_turn` seconds have gone, the turn — one or
            two flips — spread evenly over the whole of that time and ending
            nose down;
     fall   and only then does the water start to come in. He drops, nose
            first, and goes in wherever the two of them meet.

     He grows into the fish he is about to be over the up and the hang. */
  function fly(t, dt) {
    const L = fish.leap;
    const since = t - L.at;

    if (L.part !== 'fall') {
      const up = clamp(since / L.rise, 0, 1);
      const out = 1 - (1 - up) * (1 - up);          // slowing into the top
      const k = clamp(since / L.turn, 0, 1);
      const turned = k * k * (3 - 2 * k);           // slow in, slow out

      const py = fish.y;
      fish.x = lerp(L.x0, L.x1, clamp(since / L.turn, 0, 1));
      fish.y = lerp(L.y0, topOfLeap(), out);
      fish.vx = (L.x1 - L.x0) / L.turn;
      fish.vy = dt > 0 ? (fish.y - py) / dt : 0;
      fish.spin = L.spinEnd * turned;
      fish.grow = clamp(since / L.turn, 0, 1);

      // the top of the leap: the hero panels go up and away from here
      if (since >= L.rise && !L.apex) {
        L.apex = true;
        if (typeof Aquarium.onApex === 'function') Aquarium.onApex(t);
      }

      if (since >= L.turn) {
        L.part = 'fall';
        fish.spin = L.spinEnd;
        fish.grow = 1;
        fish.vx = 0;
        fish.vy = 0;
        // now the water comes
        if (Aquarium.raiseSurface) Aquarium.raiseSurface();
      }
      return;
    }

    const g = Math.max(100, Number(get('fish.leap_gravity', 1500)));
    fish.vy += g * dt;
    fish.y += fish.vy * dt;

    if (fish.vy > 0 && fish.y >= state.surfaceY) enter(t);
  }

  /* Where he hangs: near the top of the screen, but never so near that the
     turn takes his nose or his tail off it. */
  function topOfLeap() {
    const at = scene.view.h * Number(get('fish.leap_top', 0.12));
    return Math.max(at, length() * 0.55);
  }

  function swim(t, dt) {
    const b = box();
    if (!b) return;

    const p = state.pointer;

    const cruise = Number(get('fish.speed', 70));
    const top = Number(get('fish.max_speed', 1600));
    const gap = Number(get('fish.follow_gap', 90));
    const ease = Number(get('fish.follow_ease', 2.2));

    let goal = null;
    let want = cruise;
    let urgency = 1;

    /* 0. straight down. He comes out of the bowl head first and keeps going
       down until the water has finished rising — so the page opens by his
       taking it, rather than by his bobbing about at the top of it. */
    if (fish.dive) {
      const rising = typeof Aquarium.surfaceRising === 'function'
        ? Aquarium.surfaceRising() : false;
      // and while the page is taking him on down to something, he goes too
      const escort = state.escortY != null;
      if (escort) fish.dive.until = Math.max(fish.dive.until, t + 2);
      if (t > fish.dive.until || (!rising && !escort)) {
        fish.dive = null;
        fish.unwind = { at: t, from: rotation.last || 0,
                        dur: Math.max(0.05, Number(get('fish.dive_unwind', 0.8))) };
        fish.nextThink = t;
      } else {
        // When he broke out on his own, with nowhere to take the page, he
        // starts levelling out just before the water stops, so he is level
        // by the time he is free. With somewhere to go he stays nose down.
        const lead = Math.max(0, Number(get('fish.dive_level_lead', 0.6)));
        const remaining = typeof Aquarium.surfaceLeft === 'function' ? Aquarium.surfaceLeft() : 0;
        if (!fish.dive.level && !state.heading && !escort && rising && lead > 0 && remaining <= lead) {
          fish.dive.level = { at: t, dur: Math.max(0.05, remaining) };
        }
        // down to the bottom of the screen, nose first, and he holds there,
        // still swimming, until the water is all the way up
        const floor = scene.view.h - length() * Number(get('fish.dive_settle', 0.62));
        // on the way to a part of the page he holds the bottom of the screen
        // until it comes up to him, then rides it in to the top
        const y = escort ? clamp(state.escortY, length() * 0.6, floor) : floor;
        goal = { x: fish.x, y };
        // Coming up the screen while the page goes down faster still is
        // going down through the water, so nose down is still the right way
        // round for it.
        const left = Math.abs(y - fish.y);
        // On the way to a group he swims down to the bottom of the screen at
        // a dive's pace; once the group has come up to him he keeps right up
        // with it, so he gets there as the page does.
        const riding = escort && y < floor;
        const most = riding
          ? Number(get('fish.max_speed', 1600))
          : Number(get('fish.dive_speed', 230)) * (escort ? 2 : 1);
        want = left > 4 ? Math.min(most, left * (riding ? 8 : 3)) : 0;
        urgency = riding ? 6 : 2;
      }
    }

    // 1. a click he is on his way to
    if (!goal && fish.dash) {
      const d = fish.dash;
      const away = Math.hypot(d.x - fish.x, d.y - fish.y);
      if (t > d.until || away < Number(get('fish.dash_arrive', 26))) {
        fish.dash = null;
        fish.nextThink = t;
      } else {
        // A click just under the line is a place in the water like any other.
        // He is held off the surface by less on a dash than he holds himself
        // off it otherwise, so he arrives at it instead of stopping short.
        const skim = state.surfaceY + length() * Number(get('fish.dash_surface_gap', 0.05));
        goal = {
          x: clamp(d.x, b.left, b.right),
          y: clamp(d.y, Math.min(skim, b.top), b.bottom)
        };
        want = Number(get('fish.dash_speed', 1100));
        urgency = 6;
      }
    }

    // 2. something the cursor is resting on, to be circled
    if (!goal && fish.mode === 'free' && get('fish.circle', true) !== false) {
      const ring = orbit();
      if (ring) {
        const lead = Number(get('fish.circle_lead', 0.55));
        const a = Math.atan2((fish.y - ring.cy) / ring.ry,
                             (fish.x - ring.cx) / ring.rx) + lead;
        goal = {
          x: clamp(ring.cx + Math.cos(a) * ring.rx, b.left, b.right),
          y: clamp(ring.cy + Math.sin(a) * ring.ry, b.top, b.bottom)
        };
        want = Number(get('fish.circle_speed', 140));
        urgency = Math.max(0.2, Number(get('fish.circle_ease', 1.5)));
      }
    }

    // 3. somewhere a tap startled him to
    if (!goal && fish.hold) {
      if (t > fish.hold.until) { fish.hold = null; fish.nextThink = t; }
      else {
        goal = { x: fish.hold.x, y: fish.hold.y };
        want = Math.hypot(goal.x - fish.x, goal.y - fish.y) > 10 ? cruise * 3.4 : 0;
        urgency = 2.2;
      }
    }

    // 4. the cursor itself
    if (!goal && fish.mode === 'free' && following(t)) {
      goal = { x: clamp(p.x, b.left, b.right), y: clamp(p.y, b.top, b.bottom) };
      want = clamp((Math.hypot(goal.x - fish.x, goal.y - fish.y) - gap) * ease, 0, top);
    }

    // 5. his own business
    if (!goal) {
      if (!fish.target || t > fish.nextThink) newTarget(t);
      goal = fish.target || { x: fish.x, y: fish.y };
      // and if that is out past the edge of the window, he means it
      if (fish.target && fish.target.out) {
        want = cruise * Math.max(1, Number(get('fish.off_frame_speed', 3)));
        urgency = 1.6;
      }
      if (Math.hypot(goal.x - fish.x, goal.y - fish.y) < 30) {
        want = cruise * 0.25;
        if (t > fish.nextThink - 0.2) newTarget(t);
      }
    }

    const dx = goal.x - fish.x;
    const dy = goal.y - fish.y;
    const dist = Math.hypot(dx, dy) || 0.001;

    want = Math.min(want, top);
    const accel = Number(get('fish.accel', 3.2)) * urgency;
    fish.vx += ((dx / dist) * want - fish.vx) * Math.min(1, accel * dt);
    fish.vy += ((dy / dist) * want - fish.vy) * Math.min(1, accel * dt);

    fish.x += fish.vx * dt;
    fish.y += fish.vy * dt;

    /* He keeps to his water. The ceiling gives way on a dash: whatever is
       holding him off the surface the rest of the time, a click he is on his
       way to is somewhere he gets to. */
    const ceiling = fish.dash
      ? Math.min(b.top, state.surfaceY + length() * Number(get('fish.dash_surface_gap', 0.05)))
      : b.top;

    if (fish.x < b.left)   { fish.x = b.left;   fish.vx = Math.abs(fish.vx) * 0.4; }
    if (fish.x > b.right)  { fish.x = b.right;  fish.vx = -Math.abs(fish.vx) * 0.4; }
    if (fish.y < ceiling)  { fish.y = ceiling;  fish.vy = Math.abs(fish.vy) * 0.4; }
    if (fish.y > b.bottom) { fish.y = b.bottom; fish.vy = -Math.abs(fish.vy) * 0.4; }

    /* And if his back came through the line on the way, the water says so —
       once, with a gap after it, so skimming along the top is not a drum roll. */
    if (fish.mode === 'free' && state.broken && state.pour > 0.9) {
      const out = state.surfaceY - (fish.y - length() * bodyRatio() * 0.4);
      const quick = Math.abs(fish.vy) > Number(get('fish.break_speed', 140));
      if (out > 0 && quick && (t - fish.lastBreak) > Number(get('fish.break_gap', 1.1))) {
        breakSurface(t, clamp(0.35 + out / 60, 0.35, 1.1));
      }
    }

    // which way round he is drawn, with a little hysteresis so that a fish
    // hovering over the cursor doesn't flicker. Mid-roll it is left alone:
    // he is already turning, and a mirror on top of that reads as a glitch.
    if (!fish.dash && !fish.roll && !fish.dive) {
      if (fish.vx > 14) fish.facing = 1;
      if (fish.vx < -14) fish.facing = -1;
    }
  }

  /* The moment he lands: nose first, and he keeps going. */
  function enter(t) {
    fish.mode = 'free';
    fish.grow = 1;
    fish.spin = 0;
    fish.spinRate = 0;

    /* He went in head down and he carries on head down — the water taking him
       rather than catching him. The dive runs until the surface has finished
       climbing; `until` is only there in case it never says so. */
    const rise = Number(get('water.rise_time', 3.4));
    fish.dive = { until: t + rise + 3 };
    fish.vy = Math.max(Math.abs(fish.vy) * 0.5, Number(get('fish.dive_speed', 230)) * 0.8);
    fish.vx = 0;
    fish.target = null;
    fish.dash = null;

    breakSurface(t, 1.9);
    // the clock on both of the things he now does of his own accord starts
    // here, so neither of them happens the second he gets in the water
    scheduleJump(t);
    const [lo, hi] = range('fish.roll_every', 7, 18);
    fish.nextRoll = t + rand(lo, hi) * 0.6;
    if (typeof Aquarium.onSplash === 'function') Aquarium.onSplash(t);
  }

  // ---------------------------------------------------------------- draw --

  function draw(ctx, env) {
    if (!ready) return;
    update(env.t, env.dt);

    /* The drawing he is wearing, and how wide it is drawn. `flip` carries both:
       its sign says which of the two it is, its size how far through a turn he
       is. The drawing is never mirrored — at the middle of a turn one is at no
       width at all, and the other opens out of it. */
    const side = sideNow();
    const sheet = sheets[side];
    const shade = shades[side];
    if (!sheet) return;
    // a project page is laid over the water; he waits behind it, unseen
    if (document.body.classList.contains('detail-open')) return;

    const len = length();
    const h = len * shape[side];
    const rot = rotation();
    rotation.last = rot;
    const squash = Math.max(0.02, Math.abs(fish.flip));

    const wiggle = Number(get('fish.wiggle', 0.55)) * h * 0.14;
    const waves = Number(get('fish.wave_length', 1.2));
    const steady = clamp(Number(get('fish.head_steady', 0.26)), 0, 0.9);

    ctx.save();
    ctx.translate(fish.x, fish.y);
    ctx.rotate(rot);
    ctx.scale(squash, 1);

    const strips = Math.max(10, Math.round(len / 4));
    const stripW = sheet.width / strips;
    const outW = len / strips;

    // his shadow: one soft blit, under him and a little behind. Only in the
    // water — in the air there is nothing behind him for it to fall on.
    const shadow = Number(get('fish.shadow', 0.12));
    const airborne = fish.mode === 'leap' || fish.mode === 'jump';
    if (shadow > 0 && !airborne) {
      ctx.save();
      ctx.globalAlpha = shadow;
      ctx.drawImage(shade, -len / 2 + len * 0.03, -h / 2 + h * 0.1, len, h);
      ctx.restore();
    }

    // and the fish, strip by strip, with the wave running down him
    for (let i = 0; i < strips; i++) {
      // 0 at the nose, 1 at the tail, whichever way this drawing faces
      const u = (i + 0.5) / strips;
      const s = side === 'left' ? u : 1 - u;
      const amount = Math.pow(clamp((s - steady) / (1 - steady), 0, 1), 1.6);
      const dy = Math.sin(fish.phase - s * waves * Math.PI * 2) * wiggle * amount;
      ctx.drawImage(
        sheet,
        i * stripW, 0, stripW + 0.6, sheet.height,
        -len / 2 + i * outW, -h / 2 + dy, outW + 0.8, h
      );
    }
    ctx.restore();

    // the water lit up around him
    const glow = Number(get('fish.glow', 0.3));
    if (glow > 0) {
      const g = ctx.createRadialGradient(fish.x, fish.y, 0, fish.x, fish.y, len * 0.9);
      g.addColorStop(0, `rgba(255, 140, 70, ${0.16 * glow})`);
      g.addColorStop(1, 'rgba(255, 140, 70, 0)');
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(fish.x, fish.y, len * 0.9, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }
  }

  function drawBubbles(ctx, env) {
    if (!bubbles.length) return;
    ctx.save();
    for (const b of bubbles) {
      const age = (env.t - b.born) / b.life;
      const alpha = clamp(1 - age, 0, 1) * 0.5;
      ctx.strokeStyle = `rgba(226, 250, 255, ${alpha})`;
      ctx.fillStyle = `rgba(226, 250, 255, ${alpha * 0.18})`;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(b.x - b.r * 0.3, b.y - b.r * 0.3, b.r * 0.25, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(255, 255, 255, ${alpha * 0.7})`;
      ctx.fill();
    }
    ctx.restore();
  }

  // ------------------------------------------------------------- the API --

  Aquarium.fish = {
    get: () => fish,

    /* A tap that isn't the last one. */
    startle(step, final, t) {
      if (fish.mode === 'bowl') startle(step, final, t);
    },

    /* The glass has gone: he throws himself out of it, up to the top of the
       screen, and turns over there. The turn always finishes nose down. */
    release(t) {
      if (fish.mode !== 'bowl') return;
      fish.mode = 'leap';
      fish.hold = null;
      fish.dash = null;
      fish.spin = 0;
      fish.grow = 0;

      const spread = Number(get('fish.leap_spread', 170));
      const rise = Math.max(0.2, Number(get('fish.leap_rise', 1)));
      const turn = Math.max(rise, Number(get('fish.leap_turn', 2)));
      const v = scene.view;
      const x1 = clamp(fish.x + rand(-spread, spread), v.w * 0.1, v.w * 0.9);

      /* The turns, and the angle they have to finish on: whole turns for the
         look of it, and then the quarter that leaves him pointing at the
         water. Which quarter depends on the drawing he is wearing — the one
         facing left has its nose at the other end, so nose-down is the other
         way round for it. */
      const [few, many] = range('fish.leap_flips', 1, 2);
      const turns = Math.round(rand(few, many));
      const way = x1 >= fish.x ? 1 : -1;
      const noseDown = (Math.PI / 2) * (fish.facing >= 0 ? 1 : -1);

      fish.leap = {
        at: t, part: 'up', rise, turn,
        x0: fish.x, y0: fish.y, x1,
        spinEnd: turns * Math.PI * 2 * way + noseDown
      };
    },

    reset() {
      fish.mode = 'bowl';
      fish.facing = -1;
      fish.flip = -1;
      fish.dive = null;
      fish.leap = null;
      fish.unwind = null;
      fish.lastBreak = -9;
      fish.vx = -20; fish.vy = 0;
      fish.grow = 0;
      fish.spin = 0;
      fish.spinRate = 0;
      fish.dash = null;
      fish.hold = null;
      fish.target = null;
      fish.roll = null;
      fish.wantJump = null;
      fish.outside = 0;
      fish.nextRoll = fish.now + 6;
      fish.nextJump = fish.now + 7;
      bubbles.length = 0;
      const b = bowlBox();
      if (b) { fish.x = (b.left + b.right) / 2; fish.y = (b.top + b.bottom) / 2; }
    },

    place(x, y) { fish.x = x; fish.y = y; }
  };

  /* ------------------------------------------------------------- scroll --

     The water does not scroll: the canvas is fixed and the waterline is held
     at a point on the page, so going down the page is going down through the
     water rather than past a picture of it. He belongs to the water, so he
     goes with it — the page takes him along as it moves, by `scroll_drag` of
     however far it went, and he swims back to whatever he was doing from
     wherever that leaves him.

     At 1 he is pinned to the page and the window slides past him; at 0 he
     stays where he is on the screen, as he did before. Where he was going goes
     with him, or he would turn round and swim back up the moment he arrived. */

  let lastScrollY = window.scrollY;

  window.addEventListener('scroll', () => {
    const y = window.scrollY;
    const dy = y - lastScrollY;
    lastScrollY = y;
    if (!dy || !state.broken || state.autoScroll) return;

    const drag = Number(get('fish.scroll_drag', 0.8));
    if (!drag) return;
    const carry = dy * clamp(drag, 0, 1);

    fish.y -= carry;
    if (fish.target) fish.target.y -= carry;
    if (fish.dash) fish.dash.y -= carry;
    if (fish.hold) fish.hold.y -= carry;
    for (const b of bubbles) b.y -= carry;
  }, { passive: true });

  loadSprites();
  scene.add(50, draw);
  scene.add(55, drawBubbles);

})();

/* src/assets/js/10-bowl.js */
/* The bowl, the glass, and the three taps it takes.

   The bowl is drawn on the canvas, in the box the stylesheet keeps for it in
   the title section — so where it sits on the page is a CSS question, and
   everything about how it looks is a question for the `bowl` and `glass`
   blocks of src/content/aquarium.yaml.

   It is one soft shape: a body and a neck in a single path, stroked twice so
   the line reads as glass rather than as a drawn outline. There is no straight
   line and no corner anywhere on it except the rim: the lip rolls over into
   it, and the rim runs straight across, because the bowl is seen side on. Inside it there is sand, a plant and a castle.

   Tapping it rings the glass, cracks it, and sends him up to look. The last
   tap breaks it: the pieces fall, he leaps up to the top of the screen and
   turns over there, and then falls as the water comes up the screen to meet
   him. When the water has reached the top the rest of the page — which until
   then could not be scrolled to — is let in, and the overview fades in where
   the bowl was. */

(() => {
  'use strict';

  const { get, clamp, lerp, rand, motion, css } = Aquarium;
  const state = Aquarium.state;
  const scene = Aquarium.scene;
  if (!scene) return;

  const el = document.getElementById('bowl');
  const note = document.getElementById('bowl-note');
  const showcase = document.querySelector('.showcase');
  const body = document.body;

  let cracks = [];       // polylines in bowl space: 0–1 across, 0–1 down
  let shards = [];
  let shake = { at: -99, power: 0 };
  let brokeAt = 0;
  let revealed = false;
  let heading = null;    // where the page goes once the water is up, if anywhere
  let gravel = null;     // worked out once, so the stones don't crawl
  let plants = null;

  // ---------------------------------------------------------- the shape --

  /* Body and neck as one path. Curves and an arc, nothing else — the glass is
     a shape, not a diagram of a bowl. */
  function shape(b) {
    const neck = clamp(Number(get('bowl.neck', 0.46)), 0.2, 0.9);
    const neckH = clamp(Number(get('bowl.neck_height', 0.15)), 0, 0.4) * b.h;
    const flare = Number(get('bowl.flare', 0.06));
    const rx = b.w / 2;
    const ry = (b.h - neckH) / 2;
    const cx = b.x + b.w / 2;
    const cy = b.y + neckH + ry;
    const a = Math.acos(clamp(neck, -1, 1));
    return {
      cx, cy, rx, ry, a, neck,
      lipY: b.y + neckH * 0.2,
      lip: rx * (neck + flare),
      openY: cy - ry * Math.sin(a),
      openX: rx * neck
    };
  }

  /* The silhouette as a ring of points: the body round the bottom, up the
     waist of the neck, over the lip, across the rim, and down the other side.

     The ring is then drawn as one closed curve passing through every point,
     rather than as arcs and lines joined end to end. A curve through points
     has no corners in it anywhere — there is nowhere for one to be — which is
     the whole requirement, and it means the glass is described by where it
     goes rather than by a list of tangents that have to be kept in step.

     `lip_round` is how far the lip rolls over before the rim starts. The top
     of the lip and the rim are one level line: the bowl is seen side on, so
     its opening is seen edge on. */
  function outline(b) {
    const s = shape(b);
    const roll = clamp(Number(get('bowl.lip_round', 0.42)), 0, 1);

    const r = Math.max(2, s.lip * 0.4 * roll + b.w * 0.012);
    const inner = Math.max(s.lip - r * 1.2, s.lip * 0.3);
    const rimY = s.lipY - r * 0.5;
    const at = f => lerp(s.openY, s.lipY, f);

    const pts = [];
    const steps = 30;

    // the body, from the right of the opening all the way round to the left
    for (let i = 0; i <= steps; i++) {
      const th = -s.a + (Math.PI + 2 * s.a) * (i / steps);
      pts.push({ x: s.cx + s.rx * Math.cos(th), y: s.cy + s.ry * Math.sin(th) });
    }

    // up the left of the neck: in at the waist, out again to the lip
    pts.push({ x: s.cx - s.openX * 0.95, y: at(0.4) });
    pts.push({ x: s.cx - s.lip * 0.93,   y: at(0.86) });
    pts.push({ x: s.cx - s.lip,          y: s.lipY + r * 0.22 });
    // over the top of it
    pts.push({ x: s.cx - s.lip * 0.94,   y: rimY, flat: true });
    pts.push({ x: s.cx - inner,          y: rimY, flat: true });
    // and straight across the rim
    pts.push({ x: s.cx - inner * 0.45,   y: rimY, flat: true });
    pts.push({ x: s.cx + inner * 0.45,   y: rimY, flat: true });
    // the same again, the other way about
    pts.push({ x: s.cx + inner,          y: rimY, flat: true });
    pts.push({ x: s.cx + s.lip * 0.94,   y: rimY, flat: true });
    pts.push({ x: s.cx + s.lip,          y: s.lipY + r * 0.22 });
    pts.push({ x: s.cx + s.lip * 0.93,   y: at(0.86) });
    pts.push({ x: s.cx + s.openX * 0.95, y: at(0.4) });

    return { s, pts };
  }

  /* One closed curve through all of them.

     The control points are the centripetal Catmull-Rom ones: each knot is
     spaced by the square root of the distance to the next, which is what stops
     a tight turn — the lip — from looping back over itself the way an evenly
     spaced curve through the same points would.

     A `flat` point is on the level rim: the curve leaves it and arrives at it
     level, so the lip meets the rim without a bump. */
  function curveThrough(ctx, pts) {
    const n = pts.length;
    const d = (a, c) => Math.sqrt(Math.hypot(c.x - a.x, c.y - a.y)) || 1e-4;

    ctx.moveTo(pts[0].x, pts[0].y);
    for (let i = 0; i < n; i++) {
      const p0 = pts[(i - 1 + n) % n];
      const p1 = pts[i];
      const p2 = pts[(i + 1) % n];
      const p3 = pts[(i + 2) % n];

      const d1 = d(p0, p1), d2 = d(p1, p2), d3 = d(p2, p3);
      const k1 = 3 * d1 * (d1 + d2);
      const k2 = 3 * d3 * (d3 + d2);

      ctx.bezierCurveTo(
        (d1 * d1 * p2.x - d2 * d2 * p0.x + (2 * d1 * d1 + 3 * d1 * d2 + d2 * d2) * p1.x) / k1,
        p1.flat ? p1.y
          : (d1 * d1 * p2.y - d2 * d2 * p0.y + (2 * d1 * d1 + 3 * d1 * d2 + d2 * d2) * p1.y) / k1,
        (d3 * d3 * p1.x - d2 * d2 * p3.x + (2 * d3 * d3 + 3 * d3 * d2 + d2 * d2) * p2.x) / k2,
        p2.flat ? p2.y
          : (d3 * d3 * p1.y - d2 * d2 * p3.y + (2 * d3 * d3 + 3 * d3 * d2 + d2 * d2) * p2.y) / k2,
        p2.x, p2.y);
    }
    ctx.closePath();
  }

  function bowlPath(ctx, b) {
    const { s, pts } = outline(b);
    ctx.beginPath();
    curveThrough(ctx, pts);
    return s;
  }

  function waterY(b, t) {
    const level = clamp(Number(get('bowl.water_level', 0.8)), 0.05, 0.98);
    const wobbleOn = Number(get('bowl.wobble', 0.6));
    const since = t - shake.at;
    const rock = since < 2
      ? Math.sin(since * 16) * Math.exp(-since * 3) * shake.power * 0.25 * wobbleOn
      : 0;
    return b.y + b.h * (1 - level) + rock;
  }

  // ------------------------------------------------------------- insides --

  function makeGravel() {
    const count = Math.max(0, Math.round(Number(get('bowl.gravel_count', 120))));
    const out = [];
    for (let i = 0; i < count; i++) {
      out.push({
        u: Math.random(),
        v: Math.random(),
        r: rand(0.012, 0.026),
        tone: Math.random()
      });
    }
    return out;
  }

  function makePlants() {
    const out = [];
    for (let i = 0; i < 3; i++) {
      out.push({
        u: 0.24 + i * 0.05 + rand(-0.02, 0.02),
        h: rand(0.8, 1.15),
        lean: rand(-0.09, 0.09),
        phase: rand(0, Math.PI * 2),
        leaves: 5 + Math.round(rand(0, 3))
      });
    }
    return out;
  }

  /* The sand lies in a shallow mound rather than a flat band. */
  function sandTop(b, u) {
    const depth = clamp(Number(get('bowl.gravel_depth', 0.16)), 0, 0.6);
    const base = b.y + b.h * (1 - depth);
    return base - Math.sin(u * Math.PI) * b.h * depth * 0.28;
  }

  function drawInside(ctx, env) {
    const b = state.bowl;
    if (!b || state.broken) return;

    bowlPath(ctx, b);
    ctx.save();
    ctx.clip();

    // the water
    const wy = waterY(b, env.t);
    const tint = Aquarium.rgb(get('bowl.water_tint', '#e6f6fb'));
    const alpha = Number(get('bowl.water_alpha', 0.7));
    const fill = ctx.createLinearGradient(0, wy, 0, b.y + b.h);
    fill.addColorStop(0, css(tint, alpha * 0.82));
    fill.addColorStop(1, css(tint, alpha));
    ctx.fillStyle = fill;
    ctx.fillRect(b.x - 2, wy, b.w + 4, b.h);

    // where it meets the air, soft
    const meniscus = ctx.createLinearGradient(0, wy - 6, 0, wy + 8);
    meniscus.addColorStop(0, 'rgba(255, 255, 255, 0)');
    meniscus.addColorStop(0.45, 'rgba(255, 255, 255, .75)');
    meniscus.addColorStop(1, 'rgba(255, 255, 255, 0)');
    ctx.fillStyle = meniscus;
    ctx.fillRect(b.x - 2, wy - 6, b.w + 4, 14);

    drawSand(ctx, b);
    if (get('bowl.castle', true) !== false) drawCastle(ctx, b);
    drawPlants(ctx, b, env);

    ctx.restore();
  }

  function drawSand(ctx, b) {
    const depth = clamp(Number(get('bowl.gravel_depth', 0.16)), 0, 0.6);
    if (depth <= 0) return;
    if (!gravel) gravel = makeGravel();

    const warm = get('bowl.gravel_color', '#d9b27a');
    const dark = get('bowl.gravel_shade', '#b98f55');

    // the mound
    ctx.beginPath();
    ctx.moveTo(b.x - 2, sandTop(b, 0));
    for (let i = 0; i <= 20; i++) ctx.lineTo(b.x + (b.w * i) / 20, sandTop(b, i / 20));
    ctx.lineTo(b.x + b.w + 2, b.y + b.h + 4);
    ctx.lineTo(b.x - 2, b.y + b.h + 4);
    ctx.closePath();
    const bed = ctx.createLinearGradient(0, sandTop(b, 0.5), 0, b.y + b.h);
    bed.addColorStop(0, warm);
    bed.addColorStop(1, dark);
    ctx.fillStyle = bed;
    ctx.fill();

    // the stones in it
    for (const g of gravel) {
      const top = sandTop(b, g.u);
      const y = top + g.v * (b.y + b.h - top);
      ctx.fillStyle = g.tone > 0.5 ? warm : dark;
      ctx.globalAlpha = 0.55 + g.tone * 0.4;
      ctx.beginPath();
      ctx.ellipse(b.x + g.u * b.w, y, g.r * b.w, g.r * b.w * 0.74, 0, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  /* A castle, the way the ones in fish tanks look: a keep, two towers, battlements
     and a dark doorway. */
  function drawCastle(ctx, b) {
    const w = b.w * Number(get('bowl.castle_width', 0.3));
    const h = b.h * Number(get('bowl.castle_height', 0.3));
    const at = clamp(Number(get('bowl.castle_at', 0.63)), 0.1, 0.9);
    const stone = get('bowl.castle_color', '#9fb0b8');
    const dark = get('bowl.castle_shade', '#6d8089');

    const cx = b.x + at * b.w;
    const ground = sandTop(b, at) + h * 0.1;

    const keepW = w * 0.44;
    const towerW = w * 0.26;
    const towerH = h * 0.78;

    // the two towers, then the keep between them
    [-1, 1].forEach(side => {
      const x = cx + side * (keepW / 2 + towerW / 2) - towerW / 2;
      block(x, ground - towerH, towerW, towerH, 3);
    });
    block(cx - keepW / 2, ground - h, keepW, h, 3);

    // the way in
    ctx.fillStyle = dark;
    const doorW = keepW * 0.4, doorH = h * 0.4;
    ctx.beginPath();
    ctx.moveTo(cx - doorW / 2, ground);
    ctx.lineTo(cx - doorW / 2, ground - doorH * 0.55);
    ctx.quadraticCurveTo(cx, ground - doorH * 1.25, cx + doorW / 2, ground - doorH * 0.55);
    ctx.lineTo(cx + doorW / 2, ground);
    ctx.closePath();
    ctx.fill();

    // two windows up in the towers
    [-1, 1].forEach(side => {
      const x = cx + side * (keepW / 2 + towerW / 2);
      ctx.fillStyle = dark;
      ctx.beginPath();
      ctx.ellipse(x, ground - towerH * 0.62, towerW * 0.16, towerW * 0.24, 0, 0, Math.PI * 2);
      ctx.fill();
    });

    /* One tower or wall: the stone, its battlements, and a shaded side. */
    function block(x, y, bw, bh, teeth) {
      ctx.fillStyle = stone;
      ctx.beginPath();
      ctx.rect(x, y, bw, bh);
      ctx.fill();

      // the shaded right-hand side
      ctx.fillStyle = dark;
      ctx.globalAlpha = 0.35;
      ctx.fillRect(x + bw * 0.68, y, bw * 0.32, bh);
      ctx.globalAlpha = 1;

      // battlements
      const step = bw / (teeth * 2 - 1);
      ctx.fillStyle = stone;
      for (let i = 0; i < teeth; i++) {
        ctx.fillRect(x + i * step * 2, y - bh * 0.12, step, bh * 0.14);
      }
    }
  }

  function drawPlants(ctx, b, env) {
    const plantH = Number(get('bowl.plant_height', 0.5));
    if (plantH <= 0) return;
    if (!plants) plants = makePlants();

    const sway = Number(get('bowl.plant_sway', 0.5)) * motion();
    ctx.strokeStyle = get('bowl.plant_color', '#3fa34a');
    ctx.lineCap = 'round';

    for (const p of plants) {
      const x = b.x + p.u * b.w;
      const root = sandTop(b, p.u) + b.h * 0.02;
      const tip = root - b.h * plantH * p.h;
      const bend = Math.sin(env.t * 0.9 + p.phase) * b.w * 0.035 * sway;

      ctx.lineWidth = Math.max(2, b.w * 0.012);
      ctx.beginPath();
      ctx.moveTo(x, root);
      ctx.quadraticCurveTo(x + bend + p.lean * b.w, (root + tip) / 2, x + bend * 1.6, tip);
      ctx.stroke();

      for (let i = 1; i <= p.leaves; i++) {
        const f = i / (p.leaves + 1);
        const ly = lerp(root, tip, f);
        const lx = x + bend * f * 1.4 + p.lean * b.w * f;
        const side = i % 2 ? 1 : -1;
        const leaf = b.w * 0.055 * (1 - f * 0.5);
        ctx.lineWidth = Math.max(1.5, b.w * 0.008);
        ctx.beginPath();
        ctx.moveTo(lx, ly);
        ctx.quadraticCurveTo(lx + side * leaf, ly - leaf * 0.5,
                             lx + side * leaf * 1.5, ly - leaf * 1.1);
        ctx.stroke();
      }
    }
  }

  // --------------------------------------------------------------- glass --

  function drawGlass(ctx, env) {
    const b = state.bowl;
    if (!b) return;

    if (state.broken) { drawShards(ctx, env); return; }

    const tint = get('bowl.glass_tint', '#dff2f7');
    const alpha = Number(get('bowl.glass_alpha', 0.42));
    const line = Number(get('bowl.glass_line', 2.2));
    const s = bowlPath(ctx, b);

    // the pane itself, as a sheen over the water only: the air above it is
    // left fully clear
    ctx.save();
    ctx.clip();
    ctx.beginPath();
    ctx.rect(b.x - 2, waterY(b, env.t), b.w + 4, b.h);
    ctx.clip();
    const sheen = ctx.createLinearGradient(b.x, b.y, b.x + b.w, b.y + b.h);
    sheen.addColorStop(0, hexa(tint, 0.2 * alpha));
    sheen.addColorStop(0.45, hexa(tint, 0.02 * alpha));
    sheen.addColorStop(1, hexa(tint, 0.14 * alpha));
    ctx.fillStyle = sheen;
    ctx.fillRect(b.x, b.y, b.w, b.h);

    // one soft crescent down the left, and one shine across the top right
    ctx.strokeStyle = hexa('#ffffff', 0.4 * alpha);
    ctx.lineCap = 'round';
    ctx.lineWidth = Math.max(3, b.w * 0.03);
    ctx.beginPath();
    ctx.ellipse(s.cx, s.cy, s.rx * 0.84, s.ry * 0.84, 0, Math.PI * 0.6, Math.PI * 0.94);
    ctx.stroke();

    ctx.fillStyle = hexa('#ffffff', 0.1 * alpha);
    ctx.beginPath();
    ctx.ellipse(s.cx + s.rx * 0.36, s.cy - s.ry * 0.44,
                s.rx * 0.3, s.ry * 0.1, -0.5, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    // the outline, drawn twice: a wide soft one under a thin bright one
    bowlPath(ctx, b);
    ctx.lineJoin = 'round';
    ctx.lineCap = 'round';
    ctx.miterLimit = 1;
    ctx.strokeStyle = hexa(tint, 0.16 + 0.2 * alpha);
    ctx.lineWidth = line * 3;
    ctx.stroke();
    ctx.strokeStyle = hexa(tint, 0.5 + 0.4 * alpha);
    ctx.lineWidth = line;
    ctx.stroke();

    drawCracks(ctx, b);
  }

  // -------------------------------------------------------------- cracks --

  /* A crack is a run of short segments wandering away from where it was hit,
     with a couple of forks. Kept in bowl space so it stays put when the window
     is resized. */
  function makeCrack() {
    const spread = Number(get('glass.crack_spread', 0.62));
    const jitter = Number(get('glass.crack_jitter', 0.45));
    const from = { x: rand(0.3, 0.7), y: rand(0.35, 0.68) };
    const lines = [];

    const branches = 3 + Math.round(rand(0, 2));
    for (let i = 0; i < branches; i++) {
      const line = [from];
      let angle = rand(0, Math.PI * 2);
      let x = from.x, y = from.y;
      const steps = 4 + Math.round(rand(0, 4));
      const reach = spread / steps;
      for (let s = 0; s < steps; s++) {
        angle += rand(-1, 1) * jitter;
        x += Math.cos(angle) * reach * rand(0.6, 1.3);
        y += Math.sin(angle) * reach * rand(0.6, 1.3);
        if (x < 0.06 || x > 0.94 || y < 0.06 || y > 0.94) break;
        line.push({ x, y });
      }
      if (line.length > 1) lines.push(line);
    }
    return lines;
  }

  function drawCracks(ctx, b) {
    if (!cracks.length) return;
    ctx.save();
    bowlPath(ctx, b);       // a crack can't run off the edge of the glass
    ctx.clip();
    ctx.strokeStyle = hexa(get('glass.crack_color', '#ffffff'), 0.85);
    ctx.lineWidth = Number(get('glass.crack_width', 2));
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    for (const line of cracks) {
      ctx.beginPath();
      line.forEach((p, i) => {
        const x = b.x + p.x * b.w, y = b.y + p.y * b.h;
        if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      });
      ctx.stroke();
    }
    ctx.restore();
  }

  // -------------------------------------------------------------- shards --

  function makeShards(b, t) {
    const count = Math.max(4, Math.round(Number(get('glass.shards', 26))));
    const spin = Number(get('glass.shard_spin', 2.2));
    const out = [];
    const cx = b.x + b.w / 2, cy = b.y + b.h / 2;

    for (let i = 0; i < count; i++) {
      const angle = (i / count) * Math.PI * 2 + rand(-0.1, 0.1);
      const radius = (b.w / 2) * rand(0.55, 1);
      const size = b.w * rand(0.04, 0.12);
      out.push({
        x: cx + Math.cos(angle) * radius,
        y: cy + Math.sin(angle) * radius * 0.95,
        vx: Math.cos(angle) * rand(40, 220),
        vy: Math.sin(angle) * rand(20, 120) - rand(60, 260),
        rot: rand(0, Math.PI * 2),
        spin: rand(-spin, spin),
        size,
        born: t,
        points: [
          { x: 0, y: -size * rand(0.6, 1) },
          { x: size * rand(0.4, 0.9), y: size * rand(0.1, 0.5) },
          { x: -size * rand(0.3, 0.8), y: size * rand(0.3, 0.8) }
        ]
      });
    }
    return out;
  }

  function drawShards(ctx, env) {
    if (!shards.length) return;
    const g = Number(get('glass.shard_gravity', 1800));
    const life = Math.max(0.2, Number(get('glass.shard_fade', 1.6)));
    const tint = get('bowl.glass_tint', '#dff2f7');

    ctx.save();
    for (let i = shards.length - 1; i >= 0; i--) {
      const s = shards[i];
      const age = env.t - s.born;
      if (age > life) { shards.splice(i, 1); continue; }

      s.vy += g * env.dt;
      s.x += s.vx * env.dt;
      s.y += s.vy * env.dt;
      s.rot += s.spin * env.dt;

      const alpha = clamp(1 - age / life, 0, 1);
      ctx.save();
      ctx.translate(s.x, s.y);
      ctx.rotate(s.rot);
      ctx.beginPath();
      s.points.forEach((p, k) => k ? ctx.lineTo(p.x, p.y) : ctx.moveTo(p.x, p.y));
      ctx.closePath();
      ctx.fillStyle = hexa(tint, 0.3 * alpha);
      ctx.fill();
      ctx.strokeStyle = hexa('#ffffff', 0.7 * alpha);
      ctx.lineWidth = 1.2;
      ctx.stroke();
      ctx.restore();
    }
    ctx.restore();
  }

  // ------------------------------------------------------------ the taps --

  function tap() {
    if (state.broken) return;
    const t = Aquarium.clock();
    const needed = Math.max(1, Math.round(Number(get('glass.taps_to_break', 3))));

    state.taps += 1;
    shake = { at: t, power: Number(get('glass.shake', 14)) * (0.6 + state.taps * 0.25) };

    if (state.taps >= needed) { smash(t); return; }

    cracks = cracks.concat(makeCrack());
    if (state.taps === 1) Portfolio.sound.tap(1);
    else Portfolio.sound.crack(1);

    // he comes up to see what that was, and on the next one puts his nose out
    if (Aquarium.fish) Aquarium.fish.startle(state.taps, needed, t);

    if (note) {
      note.classList.add('is-going');
      setTimeout(() => note.classList.remove('is-going'), 220);
    }
  }

  /* `target`, if there is one, is where the page goes once it is open: a
     group in My work ({ group }), and optionally a project in it to open
     once he gets there ({ project }). The showcase only ever gives a group. */
  function smash(t, target) {
    heading = target || null;
    state.heading = !!heading;     // he holds his dive to the end if there is somewhere to go
    state.broken = true;
    state.breakTime = t;
    brokeAt = t;
    if (state.bowl) shards = makeShards(state.bowl, t);
    cracks = [];
    Portfolio.sound.shatter(1);

    if (el) { el.disabled = true; el.setAttribute('aria-label', 'The glass is broken'); }
    body.classList.add('is-breaking');      // the line under the bowl goes with it
    // The hero panels stop taking clicks at once, but stay where they are
    // until he reaches the top of his leap (Aquarium.onApex).
    if (showcase) showcase.inert = true;
    // On the way to a group, My work is there to be swum down to.
    if (heading) body.classList.add('is-escorting');
    if (Aquarium.fish) Aquarium.fish.release(t);
    else {
      apex();                               // no leap to wait for
      if (Aquarium.raiseSurface) Aquarium.raiseSurface();
    }

    // if something goes wrong on the way, the water still comes, the panels
    // still go and the page still opens
    const turn = Number(get('fish.leap_turn', 2));
    const rise = Number(get('water.rise_time', 3.4));
    setTimeout(apex, (Number(get('fish.leap_rise', 1)) + 0.5) * 1000);
    setTimeout(() => { if (Aquarium.raiseSurface) Aquarium.raiseSurface(); }, (turn + 1.5) * 1000);
    setTimeout(settled, (turn + rise + 4) * 1000);
  }

  /* The water has reached the top: the page opens. A second later the quote
     in the pond gives way to the name and the overview. And if a thumbnail
     broke the glass, the page goes on to what it was for. */
  function settled() {
    if (revealed) return;
    revealed = true;
    // Somewhere to go: he stays in his dive from this very frame, holding the
    // bottom of the screen, rather than levelling out first.
    if (heading && !escorting) state.escortY = Infinity;
    const wait = Math.max(0, Number(get('glass.reveal_delay', 0))) * 1000;
    setTimeout(() => {
      body.classList.add('is-settled');
      // On the way down to a group the page is still moving: the sky is cut
      // away once it gets there instead (see heroDive).
      if (!escorting) trimTop();
      reveal();
      setTimeout(() => body.classList.add('is-titled'), 1000);
      // Only if the water came up without the hero dive taking the page —
      // a missing group, say — does the page set off from here instead.
      if (heading && !escorting) goTo(heading);
    }, wait);
  }
  Aquarium.onSettled = settled;

  /* He is at the top of his leap: the hero panels rise up out of the screen,
     fading as they go (06-title.css). */
  function apex() {
    if (state.broken) body.classList.add('is-apex');
  }
  Aquarium.onApex = apex;

  /* The sky over the pond is only there for the opening. Once the page is
     open it is cut away — the band is shortened by exactly as far as the page
     has come down, and the page moved back by the same amount in the same
     frame — so nothing on the screen moves, and scrolling up stops at your
     name on the water. */
  function trimTop(by) {
    const band = document.querySelector('.band--title');
    const cut = Math.round(Math.min(window.scrollY, by === undefined ? Infinity : by));
    if (!band || cut <= 0 || band.classList.contains('is-trimmed')) return;
    state.autoScroll = true;             // he isn't to be carried by this one
    band.style.height = Math.max(0, band.offsetHeight - cut) + 'px';
    band.classList.add('is-trimmed');
    window.scrollTo({ top: window.scrollY - cut, behavior: 'instant' });
    if (Aquarium.shiftSurface) Aquarium.shiftSurface(cut);
    setTimeout(() => { if (!escorting) state.autoScroll = false; }, 120);
  }

  function untrim() {
    const band = document.querySelector('.band--title');
    if (!band) return;
    band.style.height = '';
    band.classList.remove('is-trimmed');
  }

  /* Down to a group in My work, and once there, into the project. The page
     goes at his pace rather than jumping: he stays nose down and swimming,
     holding the bottom of the screen until the group comes up to meet him,
     and the project opens once he is there. The page underneath is left
     scrolled to it, so coming back from the project lands you on its row. */
  let escorting = false;

  /* Free scroll: once he is past the quote, a scroll of the wheel (or a
     swipe) takes the page back from the dive, and it is yours from there.
     Scroll lock in Settings is the other way round: locked, the dive keeps
     the page to the end. `fish.escort_free_scroll` is where it starts.

     Dive speed in Settings is `fish.escort_speed`, the pace the dive picks
     up to. It only matters while the scroll is locked — unlocked, the page
     is yours — so the slider is off then. A viewer's own choices are
     remembered, and both are read as the dive goes, so a change made during
     one takes effect at once. */
  const freeKey = 'portfolio.freeScroll';
  const speedKey = 'portfolio.diveSpeed';
  const speedMin = Number(get('fish.escort_speed_min', 400));
  const speedMax = Number(get('fish.escort_speed_max', 2400));
  let freeScroll = get('fish.escort_free_scroll', true) !== false;
  let diveSpeed = Number(get('fish.escort_speed', 1200));
  try {
    const saved = localStorage.getItem(freeKey);
    if (saved !== null) freeScroll = saved === 'on';
    const speed = Number(localStorage.getItem(speedKey));
    if (speed) diveSpeed = speed;
  } catch (err) { /* no storage: the settings stand */ }
  diveSpeed = clamp(diveSpeed, speedMin, speedMax);

  const lockBox = document.getElementById('scroll-lock');
  const speedBar = document.getElementById('dive-speed');
  const speedOut = document.getElementById('dive-speed-value');
  if (lockBox && speedBar) {
    const paint = () => {
      lockBox.checked = !freeScroll;
      speedBar.value = String(diveSpeed);
      speedBar.disabled = freeScroll;
      speedBar.closest('.setting').classList.toggle('is-disabled', freeScroll);
      if (speedOut) speedOut.textContent = Math.round(diveSpeed / Number(get('fish.escort_speed', 1200)) * 100) + '%';
    };
    paint();
    lockBox.addEventListener('change', () => {
      freeScroll = !lockBox.checked;
      paint();
      try { localStorage.setItem(freeKey, freeScroll ? 'on' : 'off'); } catch (err) { /* fine */ }
    });
    speedBar.addEventListener('input', () => {
      diveSpeed = clamp(Number(speedBar.value), speedMin, speedMax);
      paint();
      try { localStorage.setItem(speedKey, String(diveSpeed)); } catch (err) { /* fine */ }
    });
  }

  /* The hero dive: one unbroken run from the bowl to the group. The page
     sets off with the water, at the pace the water would have taken it, and
     where the water stops it carries straight on — gathering speed up to
     the Dive speed — down past the quote and the nav into My work, and
     only slows to a stop as the group arrives at the top of the screen. He
     holds the bottom of the screen, nose down, until the group comes up to
     him, and rides it in. Called by the water as it starts to climb; `rise`
     is how that climb was going to move the page. */
  Aquarium.leadRise = rise => {
    const target = heading;
    const place = target && document.getElementById(target.group);
    if (!place || Portfolio.reduceMotion.matches) return false;

    escorting = true;
    state.autoScroll = true;
    const margin = parseFloat(getComputedStyle(place).scrollMarginTop) || 0;
    const ease = clamp(Number(get('water.rise_ease', 0.15)), 0.01, 1);
    // the water's own pace, over the steady part of its climb
    const water = Math.max(0, rise.scrollTo - rise.scrollFrom) / (rise.time * (1 - ease / 2));
    // The brake goes up with the speed, so the stop takes as long at any
    // Dive speed; the yaml's brake is the one for the yaml's speed.
    const cruise = () => Math.max(water, diveSpeed);
    const brake = () => Math.max(100, Number(get('fish.escort_brake', 1600)) *
      cruise() / Math.max(1, Number(get('fish.escort_speed', 1200))));
    let y = window.scrollY;
    let v = water;
    let last = Aquarium.clock();
    let dropped = false;      // scrolled out of it: the page is theirs

    // Past the quote is the quote's bottom edge gone up over him. Without
    // a quote, it is the page passing where the water stops.
    const quote = document.querySelector('.pond-quote');
    const past = () => {
      const fish = state.fish;
      if (!quote || !fish) return y >= rise.scrollTo;
      return quote.getBoundingClientRect().bottom < fish.y;
    };

    const unhook = () => {
      window.removeEventListener('wheel', takeOver);
      window.removeEventListener('touchmove', takeOver);
    };
    function takeOver() {
      if (dropped || !freeScroll || !past()) return;
      dropped = true;
      unhook();
      heading = null;
      state.heading = false;             // he levels out, as after a tap
      escorting = false;
      state.escortY = null;
      state.autoScroll = false;          // trimTop holds it on for its own jump
      reveal();                          // unlocked first: is-escorting is what shows My work while locked
      body.classList.remove('is-escorting');
      trimTop(rise.scrollTo);
    }
    window.addEventListener('wheel', takeOver, { passive: true });
    window.addEventListener('touchmove', takeOver, { passive: true });

    const goal = () => clamp(place.getBoundingClientRect().top + window.scrollY - margin, 0,
      document.documentElement.scrollHeight - window.innerHeight);

    const step = () => {
      if (dropped) return;
      const now = Aquarium.clock();
      const dt = Math.min(0.05, Math.max(0, now - last));
      last = now;
      const left = goal() - y;
      // past where the water stops, it picks up speed; near the group it
      // brakes, just hard enough to stop on it
      if (y >= rise.scrollTo) v += (cruise() - v) * Math.min(1, 1.6 * dt);
      v = Math.max(20, Math.min(v, Math.sqrt(2 * brake() * Math.max(0, left))));
      y = Math.min(y + v * dt, goal());
      window.scrollTo({ top: y, behavior: 'instant' });
      state.escortY = place.getBoundingClientRect().top + margin * 0.5;
      if (goal() - y > 0.5) { requestAnimationFrame(step); return; }
      arrive();
    };

    // There: once he is too, the sky above the pond is cut away (nothing on
    // screen moves) and he is let go.
    const until = Aquarium.clock() + 1.5;
    const arrive = () => {
      if (dropped) return;
      state.escortY = place.getBoundingClientRect().top + margin * 0.5;
      const fish = state.fish;
      const near = !fish || Math.abs(fish.y - Math.max(state.escortY, 0)) < 60;
      if (!near && Aquarium.clock() < until) { requestAnimationFrame(arrive); return; }
      unhook();
      heading = null;
      trimTop(rise.scrollTo);
      setTimeout(() => {
        escorting = false;
        state.autoScroll = false;
        state.escortY = null;
        body.classList.remove('is-escorting');
      }, 150);
    };
    requestAnimationFrame(step);
    return true;
  };

  function goTo(target) {
    heading = null;
    const place = document.getElementById(target.group);
    if (!place) return;

    const margin = parseFloat(getComputedStyle(place).scrollMarginTop) || 0;
    const from = window.scrollY;
    const to = Math.max(0, Math.min(
      place.getBoundingClientRect().top + from - margin,
      document.documentElement.scrollHeight - window.innerHeight));
    const speed = Math.max(100, diveSpeed);
    const time = Portfolio.reduceMotion.matches ? 0.01
      : clamp(Math.abs(to - from) / speed, 1.2, 5);
    const start = Aquarium.clock();

    escorting = true;
    state.autoScroll = true;
    const step = () => {
      const p = clamp((Aquarium.clock() - start) / time, 0, 1);
      const eased = p * p * (3 - 2 * p);
      window.scrollTo({ top: lerp(from, to, eased), behavior: 'instant' });
      state.escortY = place.getBoundingClientRect().top + margin * 0.5;
      if (p < 1) { requestAnimationFrame(step); return; }
      arrive();
    };

    // The page is there; the project opens once he is too, or soon after.
    const until = Aquarium.clock() + time + 1.5;
    const arrive = () => {
      state.escortY = place.getBoundingClientRect().top + margin * 0.5;
      const fish = state.fish;
      const near = !fish || Math.abs(fish.y - Math.max(state.escortY, 0)) < 60;
      if (!near && Aquarium.clock() < until) { requestAnimationFrame(arrive); return; }
      setTimeout(() => {
        escorting = false;
        state.autoScroll = false;
        state.escortY = null;
        if (!target.project) return;
        const link = place.querySelector(`.entry-link[data-project="${target.project}"]`);
        if (link) link.click();
      }, 250);
    };
    requestAnimationFrame(step);
  }

  function reveal() {
    body.classList.remove('is-locked');
    document.documentElement.classList.remove('is-locked');
    body.classList.add('is-free');
    fold();
    if (Aquarium.remeasure) Aquarium.remeasure();
  }

  /* The bowl's space is kept, but the button itself goes, so there is
     nothing left there to tab to. */
  function fold() {
    if (!el) return;
    el.style.opacity = '0';
    el.style.visibility = 'hidden';
  }

  function unfold() {
    if (!el) return;
    el.style.opacity = '';
    el.style.visibility = '';
  }

  // -------------------------------------------------------------- update --

  function measure(env) {
    if (!el) { state.bowl = null; return; }
    const r = el.getBoundingClientRect();
    if (!r.width || !r.height) { state.bowl = null; return; }

    const since = env.t - shake.at;
    const jolt = since < 1.4
      ? Math.sin(since * 38) * Math.exp(-since * Number(get('glass.shake_decay', 7))) * shake.power
      : 0;

    state.bowl = { x: r.left + jolt, y: r.top, w: r.width, h: r.height };
  }

  function pour(env) {
    if (!state.broken) { state.pour = 0; return; }
    const time = Math.max(0.1, Number(get('glass.pour_time', 0.9)));
    state.pour = clamp((env.t - brokeAt) / time, 0, 1);
  }

  // ---------------------------------------------------------------- wire --

  if (el) {
    el.addEventListener('click', event => {
      event.preventDefault();
      tap();
    });
  }

  /* The lock. Added here rather than written into the HTML, so that a page
     whose script never ran is simply the portfolio, scrollable as usual. */
  function lock() {
    if (get('glass.lock_page', true) === false) return;
    if (state.deepLinked) return;          // they came for a project page
    body.classList.add('is-locked');
    document.documentElement.classList.add('is-locked');
    // A #work or #contact left in the address from last time would have the
    // browser jump down to it as the page loads, and the lock would then
    // hold it there. Locked, the page belongs at the top.
    if (location.hash) history.replaceState(history.state, '', location.pathname + location.search);
    window.scrollTo(0, 0);
  }

  // The browser may still put the scroll back after this script has run —
  // on load, or coming back to the tab from the history. While the page is
  // locked, it goes straight back to the top.
  // And whatever else moves it — a late jump to an anchor, a restored
  // position, a key — is undone the moment it happens: until the glass
  // breaks, the page does not move from the top. (Once it breaks, the water
  // takes the page down, and this stands aside.)
  const toTop = () => {
    if (state.broken || !body.classList.contains('is-locked')) return;
    if (window.scrollY !== 0) window.scrollTo({ top: 0, behavior: 'instant' });
  };
  window.addEventListener('load', toTop);
  window.addEventListener('pageshow', toTop);
  window.addEventListener('scroll', toTop, { passive: true });

  // Anyone who tabs to the skip link wants the page, not the puzzle.
  const skip = document.getElementById('skip');
  if (skip) skip.addEventListener('click', event => {
    if (state.broken) return;
    event.preventDefault();
    smash(Aquarium.clock(), { group: 'work' });
  });

  /* The panel clicked grows a little and the other two fade back at once,
     before anything else happens (hero.picked_* in aquarium.yaml). */
  function pick(link) {
    if (!showcase) return;
    const item = link.closest('.showcase-item');
    showcase.style.setProperty('--picked-scale', String(get('hero.picked_scale', 1.06)));
    showcase.style.setProperty('--picked-fade', String(get('hero.picked_fade', 0.45)));
    showcase.style.setProperty('--picked-time', `${Number(get('hero.picked_time', 0.35))}s`);
    showcase.classList.add('is-picked');
    if (item) item.classList.add('is-chosen');
  }
  function unpick() {
    if (!showcase) return;
    showcase.classList.remove('is-picked');
    showcase.querySelectorAll('.is-chosen').forEach(item => item.classList.remove('is-chosen'));
  }

  // A thumbnail on the opening screen breaks the glass too, and then takes
  // the page down to its part of My work. Nothing is opened: it stops there.
  document.querySelectorAll('.showcase-link').forEach(link => {
    link.addEventListener('click', event => {
      if (state.broken) return;
      event.preventDefault();
      pick(link);
      smash(Aquarium.clock(), { group: link.dataset.group });
    });
  });

  Aquarium.break_ = target => { if (!state.broken) smash(Aquarium.clock(), target); };
  Aquarium.breakGlass = Aquarium.break_;
  Aquarium.reset = () => {
    state.broken = false;
    state.taps = 0;
    state.pour = 0;
    revealed = false;
    cracks = [];
    shards = [];
    gravel = null;
    plants = null;
    body.classList.remove('is-free');
    body.classList.remove('is-breaking');
    body.classList.remove('is-settled');
    body.classList.remove('is-titled');
    body.classList.remove('is-escorting');
    body.classList.remove('is-apex');
    if (showcase) showcase.inert = false;
    unpick();
    heading = null;
    state.heading = false;
    untrim();
    unfold();
    if (el) { el.disabled = false; el.setAttribute('aria-label', 'Tap to break the glass'); }
    if (Aquarium.fish) Aquarium.fish.reset();
    if (Aquarium.dropSurface) Aquarium.dropSurface();
    lock();
  };

  // a project page is laid over the water, and the bowl stays behind it
  const covered = () => body.classList.contains('detail-open');
  scene.add(20, (ctx, env) => { measure(env); pour(env); if (!covered()) drawInside(ctx, env); });
  scene.add(75, (ctx, env) => { if (!covered()) drawGlass(ctx, env); });

  lock();
  // The lock (or not) is in place, so the boot cover from the <head> can go.
  document.documentElement.classList.remove('is-booting');

  // --------------------------------------------------------------- bits --

  function hexa(hex, alpha) {
    const c = Aquarium.rgb(hex);
    return `rgba(${c.r}, ${c.g}, ${c.b}, ${clamp(alpha, 0, 1)})`;
  }

})();

/* src/assets/js/11-settings.js */
/* The gear in the top right corner, and the small panel it opens. What the
   settings in it do is wired up where they are used (Scroll lock and Dive
   speed in 10-bowl.js); this only opens and closes it. It closes on a
   second click, a click anywhere else, or Escape. */

(() => {
  'use strict';

  const btn = document.getElementById('settings-toggle');
  const panel = document.getElementById('settings');
  if (!btn || !panel) return;

  const open = () => !panel.hidden;
  const show = on => {
    panel.hidden = !on;
    btn.setAttribute('aria-expanded', String(on));
  };

  btn.addEventListener('click', () => show(!open()));

  document.addEventListener('click', event => {
    if (open() && !panel.contains(event.target) && !btn.contains(event.target)) show(false);
  });

  // Escape closes the panel first; the detail page's own Escape waits for
  // the next press.
  document.addEventListener('keydown', event => {
    if (event.key !== 'Escape' || !open()) return;
    event.stopImmediatePropagation();
    show(false);
    btn.focus();
  }, true);
})();

/* src/assets/js/12-models.js */
/* The Gallery's 3D models. The viewer itself is <model-viewer>, loaded by
   the page only when there are models. Each model is fetched once its panel
   comes on screen, not with the page: the detail pages start hidden, which
   <model-viewer>'s own lazy loading doesn't notice them leaving. It stops
   turning by itself while somebody is turning it, and starts again
   (auto-rotate-delay, 2.5s) once they let go — and as it does, it comes
   back to the middle of the view at its first zoom. And the "Drag to turn"
   hint goes once somebody has.

   Alt and the middle button drag the model across the view instead of
   turning it.

   An animation showcase has a row of buttons under it, one per animation
   in the file: pressing one plays it on the model from its start, on a
   loop, and marks that button.

   The round button in the top left of each view puts the zoom back where
   it started, leaving the angle as it is. */

(() => {
  'use strict';

  const viewers = document.querySelectorAll('.model-stage model-viewer[data-src]');
  const load = viewer => { if (!viewer.src) viewer.src = viewer.dataset.src; };

  const seen = window.IntersectionObserver && new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (!entry.isIntersecting) return;
      load(entry.target);
      seen.unobserve(entry.target);
    });
  }, { rootMargin: '200px' });

  viewers.forEach(viewer => {
    if (seen) seen.observe(viewer);
    else load(viewer);

    /* Back to the middle, at the first zoom, the moment it starts turning
       by itself again: auto-rotate-delay after the last time anybody
       touched it. The angle is left as it is. */
    const delay = Number(viewer.getAttribute('auto-rotate-delay')) || 3000;
    let pressed = false;
    let settle = 0;
    const later = () => {
      clearTimeout(settle);
      settle = setTimeout(() => {
        if (pressed) return;               // still held: letting go asks again
        const orbit = viewer.getCameraOrbit();
        viewer.cameraTarget = 'auto auto auto';
        viewer.cameraOrbit = `${orbit.theta}rad ${orbit.phi}rad auto`;
        viewer.fieldOfView = 'auto';
      }, delay);
    };

    /* Alt and the middle button: a drag across the view. <model-viewer>'s
       own panning is off (disable-pan), so the camera's target is moved by
       hand — along the screen's right and up, by as far as the pointer went
       at the model's distance. Caught on the way in, before the viewer can
       take it as a turn. */
    let pan = null;

    // held still under the pointer for as long as it is pressed
    viewer.addEventListener('pointerdown', event => {
      pressed = true;
      viewer.autoRotate = false;
      if (event.button !== 1 || !event.altKey) return;
      event.preventDefault();
      event.stopPropagation();
      pan = { id: event.pointerId, x: event.clientX, y: event.clientY };
      viewer.setPointerCapture(event.pointerId);
      viewer.classList.add('is-panning');
    }, true);
    // and the browser's own middle-button scrolling stays out of it
    viewer.addEventListener('mousedown', event => {
      if (event.button === 1 && event.altKey) event.preventDefault();
    }, true);

    viewer.addEventListener('pointermove', event => {
      if (!pan || event.pointerId !== pan.id) return;
      const dx = event.clientX - pan.x;
      const dy = event.clientY - pan.y;
      pan.x = event.clientX;
      pan.y = event.clientY;

      const { theta, phi, radius } = viewer.getCameraOrbit();
      const fov = viewer.getFieldOfView() * Math.PI / 180;
      const k = 2 * radius * Math.tan(fov / 2) / Math.max(1, viewer.clientHeight);
      // the screen's right and up, in the model's space
      const right = { x: Math.cos(theta), z: -Math.sin(theta) };
      const up = { x: -Math.cos(phi) * Math.sin(theta), y: Math.sin(phi),
                   z: -Math.cos(phi) * Math.cos(theta) };
      const to = viewer.getCameraTarget();
      viewer.cameraTarget = `${to.x + (up.x * dy - right.x * dx) * k}m ` +
                            `${to.y + up.y * dy * k}m ` +
                            `${to.z + (up.z * dy - right.z * dx) * k}m`;
      viewer.jumpCameraToGoal();
      viewer.parentElement.classList.add('is-turned');
      later();
    });
    const endPan = event => {
      if (!pan || event.pointerId !== pan.id) return;
      pan = null;
      viewer.classList.remove('is-panning');
    };
    viewer.addEventListener('pointerup', endPan);
    viewer.addEventListener('pointercancel', endPan);

    // let go anywhere, the drag may have left the panel
    const resume = () => {
      if (!viewer.autoRotate) viewer.autoRotate = true;
      if (pressed) { pressed = false; later(); }
    };
    window.addEventListener('pointerup', resume);
    window.addEventListener('pointercancel', resume);

    const stage = viewer.closest('.model');
    const clips = stage ? stage.querySelectorAll('.clip[data-clip]') : [];
    clips.forEach(btn => btn.addEventListener('click', () => {
      load(viewer);
      viewer.animationName = btn.dataset.clip;
      viewer.currentTime = 0;
      viewer.play();
      clips.forEach(other => other.setAttribute('aria-pressed', String(other === btn)));
    }));

    const reset = stage && stage.querySelector('.model-reset');
    if (reset) reset.addEventListener('click', () => {
      const orbit = viewer.getCameraOrbit();
      viewer.cameraOrbit = `${orbit.theta}rad ${orbit.phi}rad auto`;
      viewer.fieldOfView = 'auto';
    });

    viewer.addEventListener('camera-change', event => {
      if (event.detail && event.detail.source === 'user-interaction') {
        viewer.parentElement.classList.add('is-turned');
        later();                           // a turn or a zoom puts it off
      }
    });
  });
})();

/* src/assets/js/13-game.js */
/* Game Mode: the joystick under the overview swaps the page for another
   view, behind a band of water that sweeps across the screen. Left to right
   on the way in, right to left on the way out; the views change while the
   band covers the whole screen, so neither is ever seen half drawn. The
   view itself is still under construction (sections/game.html). */

(() => {
  'use strict';

  const toggle = document.getElementById('game-toggle');
  const layer  = document.getElementById('game-layer');
  const back   = document.getElementById('game-back');
  const sweep  = document.getElementById('sweep');
  const main   = document.getElementById('main');
  if (!toggle || !layer || !sweep) return;

  const get = (path, fallback) => window.Aquarium ? Aquarium.get(path, fallback) : fallback;
  const isOpen = () => !layer.hidden;
  let running = false;

  function show(on) {
    layer.hidden = !on;
    document.body.classList.toggle('game-open', on);
    toggle.setAttribute('aria-expanded', String(on));
    if (main) {
      main.inert = on;
      if (on) main.setAttribute('aria-hidden', 'true');
      else main.removeAttribute('aria-hidden');
    }
  }

  /* The band is 160vw wide and leans by `sweep_angle`, so its edges stick
     out by tan(angle) × half the screen's height either side of its middle.
     It starts wholly off one side, covers the screen at its halfway point,
     and leaves wholly off the other. The two halves meet at the same speed:
     it gathers pace on the way in and loses it on the way out. */
  function cross(forward, swap) {
    const reduce = Portfolio.reduceMotion.matches;
    const time = Math.max(0, Number(get('game.sweep_time', 1.1))) * 1000;
    if (reduce || !time || typeof sweep.animate !== 'function') { swap(); return; }

    running = true;
    const w = window.innerWidth;
    const h = window.innerHeight;
    const band = w * 1.6;
    const angle = Number(get('game.sweep_angle', 10));
    const lean = Math.abs(Math.tan(angle * Math.PI / 180)) * h / 2 + 2;
    const off = -band - lean;          // wholly off the left
    const on  = w + lean;              // wholly off the right
    const mid = (w - band) / 2;        // covering the screen
    const from = forward ? off : on;
    const to   = forward ? on : off;
    // the top edge leans the way it is going
    const at = x => ({ transform: `translateX(${x}px) skewX(${forward ? -angle : angle}deg)` });

    sweep.classList.add('is-running');
    const half = time / 2;
    sweep.animate([at(from), at(mid)], { duration: half, easing: 'cubic-bezier(.45, 0, .8, .45)', fill: 'forwards' })
      .finished.then(() => {
        swap();
        return sweep.animate([at(mid), at(to)], { duration: half, easing: 'cubic-bezier(.2, .55, .55, 1)', fill: 'forwards' }).finished;
      })
      .finally(() => {
        sweep.getAnimations().forEach(a => a.cancel());
        sweep.classList.remove('is-running');
        running = false;
      });
  }

  function open() {
    if (running || isOpen()) return;
    cross(true, () => {
      show(true);
      const title = document.getElementById('game-title');
      if (title) title.focus({ preventScroll: true });
    });
  }

  function close() {
    if (running || !isOpen()) return;
    cross(false, () => {
      show(false);
      toggle.focus({ preventScroll: true });
    });
  }

  toggle.addEventListener('click', open);
  if (back) back.addEventListener('click', close);

  document.addEventListener('keydown', event => {
    if (event.key === 'Escape' && isOpen()) close();
  });
})();
